// ---------- Segurança de senha (hash com salt via Web Crypto API nativa do navegador) ----------

function bufToHex(buf) {
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

function hexToBuf(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
  return bytes.buffer;
}

function gerarSaltHex() {
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return bufToHex(arr.buffer);
}
async function hashSenha(senha, saltHex) {
  const enc = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey("raw", enc.encode(senha), { name: "PBKDF2" }, false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt: hexToBuf(saltHex), iterations: 100000, hash: "SHA-256" },
    keyMaterial,
    256
  );
  return bufToHex(bits);
}

async function seedUsers() {
  const salt = gerarSaltHex();
  const senhaHash = await hashSenha("admin123", salt);
  return [
    { id: "u1", nome: "Administrador", usuario: "admin", salt, senhaHash, perfil: "Administrador", status: "ativo" },
  ];
}

