// Data no formato YYYY-MM-DD usando o horário LOCAL do dispositivo (evita bug de fuso horário do toISOString)

function localISO(d = new Date()) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

// Segunda-feira da semana de uma data qualquer, no formato YYYY-MM-DD

function segundaFeiraDe(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const dia = d.getDay(); // 0 = domingo
  const diff = dia === 0 ? -6 : 1 - dia;
  d.setDate(d.getDate() + diff);
  return localISO(d);
}

// Número do lote = dia do ano (001-365/366), conforme regra da Parte 3

function diaDoAno(date) {
  const inicio = new Date(date.getFullYear(), 0, 1);
  const diff = date - inicio;
  return Math.floor(diff / 86400000) + 1;
}

function numeroLote(date) {
  return String(diaDoAno(date)).padStart(3, "0");
}

function loteKeyFor(date) {
  return `lote:${date.getFullYear()}-${numeroLote(date)}`;
}

function loteVazio(date) {
  return {
    numero: numeroLote(date),
    ano: date.getFullYear(),
    data: localISO(date),
    status: "aberto",
    recheios: [],
    massas: [],
    modelagens: [],
    embalagens: [],
    perdas: [],
    carrinhos: [],
    finalizacoesEmbalagem: [],
  };
}

// Indicador de rendimento (Parte 3, regra 3.11)

function statusRendimento(produzido, esperado) {
  if (!(esperado > 0)) return { pct: null, emoji: "⚪", label: "Sem meta", color: "#8A837C" };
  const pct = (produzido / esperado) * 100;
  if (pct > 105) return { pct, emoji: "🔵", label: "Acima do esperado", color: "#2563EB" };
  if (pct >= 95) return { pct, emoji: "🟢", label: "Bom", color: "#16A34A" };
  if (pct >= 90) return { pct, emoji: "🟡", label: "OK", color: "#CA8A04" };
  return { pct, emoji: "🔴", label: "Ruim", color: "#C8161D" };
}

const ETAPA_LABEL = { recheio: "Recheio", massa: "Massa", catupiry: "Catupiry", farinha: "Farinha" };

// Status de validade de uma sobra em estoque

function statusSobra(sobra) {
  const hoje = new Date(localISO() + "T00:00:00");
  const venc = new Date(sobra.validade + "T00:00:00");
  const dias = Math.round((venc - hoje) / 86400000);
  if (dias < 0) return { emoji: "🔴", label: "Vencida", dias, color: "#C8161D" };
  if (dias === 0) return { emoji: "🔴", label: "Vence hoje", dias, color: "#C8161D" };
  if (dias <= 2) return { emoji: "🟡", label: `Vence em ${dias}d`, dias, color: "#CA8A04" };
  return { emoji: "🟢", label: `Vence em ${dias}d`, dias, color: "#16A34A" };
}

function fmtData(iso) {
  return new Date(iso + "T00:00:00").toLocaleDateString("pt-BR");
}

const DIAS_SEMANA = ["Segunda-feira", "Terça-feira", "Quarta-feira", "Quinta-feira", "Sexta-feira", "Sábado", "Domingo"];

function diasDaSemana(segundaISO) {
  const out = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(segundaISO + "T00:00:00");
    d.setDate(d.getDate() + i);
    out.push(localISO(d));
  }
  return out;
}

function planoVazio() {
  return { matutino: [], vespertino: [] };
}

function iconeProduto(nome) {
  const n = nome.toLowerCase();
  if (n.includes("coxinha")) return "🍗";
  if (n.includes("risole")) return "🥟";
  if (n.includes("queijo") || n.includes("delícia")) return "🧀";
  if (n.includes("kibe")) return "🥙";
  if (n.includes("pastel")) return "🥟";
  if (n.includes("churros")) return "🍩";
  if (n.includes("bacalhau")) return "🐟";
  if (n.includes("pamonha")) return "🌽";
  if (n.includes("salsicha") || n.includes("enroladinho")) return "🌭";
  if (n.includes("mandioca")) return "🥔";
  if (n.includes("napolitano")) return "🍕";
  if (n.includes("camarão") || n.includes("camarao")) return "🍤";
  if (n.includes("peru") || n.includes("ricota")) return "🍗";
  if (n.includes("alho")) return "🧄";
  return "🍽️";
}

