export default function App() {
  const [booting, setBooting] = useState(true);
  const [users, setUsers] = useState([]);
  const [requests, setRequests] = useState([]);
  const [produtos, setProdutos] = useState([]);
  const [planos, setPlanos] = useState([]);
  const [lote, setLote] = useState(null);
  const [lotesAbertos, setLotesAbertos] = useState([]);
  const [historicoLotes, setHistoricoLotes] = useState([]);
  const [logs, setLogs] = useState([]);
  const [sobras, setSobras] = useState([]);
  const [turnoAtivo, setTurnoAtivo] = useState(new Date().getHours() < 13 ? "matutino" : "vespertino");
  const [dataTrabalho, setDataTrabalho] = useState(localISO());
  const [trocandoData, setTrocandoData] = useState(false);
  const [view, setView] = useState("login"); // login | signup | app
  const [currentUser, setCurrentUser] = useState(null);
  const [profileOpen, setProfileOpen] = useState(false);
  const [tab, setTab] = useState("home");
  const [screen, setScreen] = useState("none"); // none | planejamento
  const [toast, setToast] = useState(null);

  useEffect(() => {
    let cancelled = false;

    async function boot() {
      let u = await seedUsers();
      let r = [];
      let p = seedProdutos();
      let pl = [];
      let lt = null;
      let sb = [];
      let lg = [];
      const hoje = new Date();
      const loteKey = loteKeyFor(hoje);

      try {
        const res = await window.storage.get("usuarios", true);
        u = JSON.parse(res.value);
        // Migração: contas antigas (de antes do hash de senha) são convertidas automaticamente
        let precisaMigrar = false;
        u = await Promise.all(
          u.map(async (usr) => {
            if (!usr.senhaHash && usr.senha) {
              precisaMigrar = true;
              const salt = gerarSaltHex();
              const senhaHash = await hashSenha(usr.senha, salt);
              const { senha, ...resto } = usr;
              return { ...resto, salt, senhaHash };
            }
            return usr;
          })
        );
        if (precisaMigrar) {
          try {
            await window.storage.set("usuarios", JSON.stringify(u), true);
          } catch {
            // segue com a migração em memória mesmo se o storage falhar
          }
        }
      } catch {
        try {
          await window.storage.set("usuarios", JSON.stringify(u), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      try {
        const res = await window.storage.get("solicitacoes", true);
        r = JSON.parse(res.value);
      } catch {
        try {
          await window.storage.set("solicitacoes", JSON.stringify(r), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      try {
        const res = await window.storage.get("produtos", true);
        p = JSON.parse(res.value);
        p = p.map((prod) => ({
          ...prod,
          temCatupiry: prod.temCatupiry ?? (prod.pesoCatupiry > 0 || prod.id === "coxinha-com-catupiry"),
        }));
      } catch {
        try {
          await window.storage.set("produtos", JSON.stringify(p), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      try {
        const res = await window.storage.get("planejamentos", true);
        pl = JSON.parse(res.value);
      } catch {
        try {
          await window.storage.set("planejamentos", JSON.stringify(pl), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      try {
        const res = await window.storage.get(loteKey, true);
        lt = JSON.parse(res.value);
        if (!lt.carrinhos) lt.carrinhos = [];
        if (!lt.finalizacoesEmbalagem) lt.finalizacoesEmbalagem = [];
      } catch {
        lt = loteVazio(hoje);
        try {
          await window.storage.set(loteKey, JSON.stringify(lt), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      try {
        const res = await window.storage.get("sobras", true);
        sb = JSON.parse(res.value);
      } catch {
        try {
          await window.storage.set("sobras", JSON.stringify(sb), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      try {
        const res = await window.storage.get("logs", true);
        lg = JSON.parse(res.value);
      } catch {
        try {
          await window.storage.set("logs", JSON.stringify(lg), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }

      if (!cancelled) {
        setUsers(u);
        setRequests(r);
        setProdutos(p);
        setPlanos(pl);
        setLote(lt);
        setSobras(sb);
        setLogs(lg);
        setBooting(false);
      }
    }

    boot().catch(async () => {
      // garante que o app nunca fique travado na tela de carregamento
      if (!cancelled) {
        setUsers(await seedUsers());
        setRequests([]);
        setProdutos(seedProdutos());
        setPlanos([]);
        setLote(loteVazio(new Date()));
        setSobras([]);
        setLogs([]);
        setBooting(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, []);

  function showToast(msg, kind = "ok") {
    setToast({ msg, kind });
    setTimeout(() => setToast(null), 3200);
  }

  async function persistUsers(next) {
    setUsers(next);
    try {
      await window.storage.set("usuarios", JSON.stringify(next), true);
    } catch {
      showToast("Não foi possível sincronizar. Os dados ficaram salvos apenas neste dispositivo.", "warn");
    }
  }

  async function salvarUsuario(dados, idExistente) {
    const next = users.map((u) => (u.id === idExistente ? { ...u, ...dados } : u));
    await persistUsers(next);
    registrarLog("usuario_editado", currentUser.nome, `${dados.nome || ""} (perfil: ${dados.perfil})`);
    showToast("Usuário atualizado com sucesso.");
  }

  async function criarUsuarioDireto({ nome, usuario, senha, perfil }) {
    if (users.some((x) => x.usuario === usuario) || requests.some((x) => x.usuario === usuario)) {
      return { ok: false, msg: "Esse nome de usuário já está em uso." };
    }
    const salt = gerarSaltHex();
    const senhaHash = await hashSenha(senha, salt);
    const novo = { id: "u" + Date.now(), nome, usuario, salt, senhaHash, perfil, status: "ativo" };
    await persistUsers([...users, novo]);
    registrarLog("usuario_criado", currentUser.nome, `${nome} (@${usuario}, perfil: ${perfil})`);
    showToast("Usuário criado com sucesso.");
    return { ok: true };
  }

  async function redefinirSenhaUsuario(userId, novaSenha) {
    const alvo = users.find((u) => u.id === userId);
    if (!alvo) return;
    const salt = gerarSaltHex();
    const senhaHash = await hashSenha(novaSenha, salt);
    const next = users.map((u) => (u.id === userId ? { ...u, salt, senhaHash } : u));
    await persistUsers(next);
    registrarLog("senha_redefinida", currentUser.nome, `Redefiniu a senha de ${alvo.nome}`);
    showToast(`Senha de ${alvo.nome} redefinida.`);
  }

  async function alternarStatusUsuario(userId) {
    const alvo = users.find((u) => u.id === userId);
    if (!alvo) return;
    if (alvo.id === currentUser.id) {
      showToast("Você não pode bloquear a si mesmo.", "warn");
      return;
    }
    const ativosAdmin = users.filter((u) => u.perfil === "Administrador" && u.status === "ativo");
    if (alvo.perfil === "Administrador" && alvo.status === "ativo" && ativosAdmin.length <= 1) {
      showToast("Não é possível bloquear o único Administrador ativo.", "warn");
      return;
    }
    const novoStatus = alvo.status === "ativo" ? "bloqueado" : "ativo";
    const next = users.map((u) => (u.id === userId ? { ...u, status: novoStatus } : u));
    await persistUsers(next);
    registrarLog(novoStatus === "bloqueado" ? "usuario_bloqueado" : "usuario_desbloqueado", currentUser.nome, alvo.nome);
    showToast(`${alvo.nome} ${novoStatus === "bloqueado" ? "bloqueado" : "reativado"}.`);
  }

  async function excluirUsuario(userId) {
    const alvo = users.find((u) => u.id === userId);
    if (!alvo) return;
    if (alvo.id === currentUser.id) {
      showToast("Você não pode excluir a si mesmo.", "warn");
      return;
    }
    const ativosAdmin = users.filter((u) => u.perfil === "Administrador" && u.status === "ativo");
    if (alvo.perfil === "Administrador" && ativosAdmin.length <= 1) {
      showToast("Não é possível excluir o único Administrador.", "warn");
      return;
    }
    const next = users.filter((u) => u.id !== userId);
    await persistUsers(next);
    registrarLog("usuario_excluido", currentUser.nome, alvo.nome);
    showToast(`${alvo.nome} excluído.`);
  }

  async function persistRequests(next) {
    setRequests(next);
    try {
      await window.storage.set("solicitacoes", JSON.stringify(next), true);
    } catch {
      showToast("Não foi possível sincronizar. Os dados ficaram salvos apenas neste dispositivo.", "warn");
    }
  }
  async function persistPlanos(next) {
    setPlanos(next);
    try {
      await window.storage.set("planejamentos", JSON.stringify(next), true);
    } catch {
      showToast("Não foi possível sincronizar. Os dados ficaram salvos apenas neste dispositivo.", "warn");
    }
  }
  async function persistLote(next) {
    setLote(next);
    try {
      await window.storage.set(loteKeyFor(new Date(next.data + "T00:00:00")), JSON.stringify(next), true);
    } catch {
      showToast("Não foi possível sincronizar. Os dados ficaram salvos apenas neste dispositivo.", "warn");
    }
  }

  async function trocarDataTrabalho(novaDataISO) {
    setTrocandoData(true);
    try {
      const dataObj = new Date(novaDataISO + "T00:00:00");
      const key = loteKeyFor(dataObj);
      let lt;
      try {
        const res = await window.storage.get(key, true);
        lt = JSON.parse(res.value);
        if (!lt.carrinhos) lt.carrinhos = [];
        if (!lt.finalizacoesEmbalagem) lt.finalizacoesEmbalagem = [];
      } catch {
        lt = loteVazio(dataObj);
        try {
          await window.storage.set(key, JSON.stringify(lt), true);
        } catch {
          // segue com os dados em memória mesmo se o storage falhar
        }
      }
      setLote(lt);
      setDataTrabalho(novaDataISO);
      showToast(`Agora lançando dados no Lote ${lt.numero} (${fmtData(novaDataISO)}).`);
    } finally {
      setTrocandoData(false);
    }
  }

  async function persistSobras(next) {
    setSobras(next);
    try {
      await window.storage.set("sobras", JSON.stringify(next), true);
    } catch {
      showToast("Não foi possível sincronizar. Os dados ficaram salvos apenas neste dispositivo.", "warn");
    }
  }

  async function registrarLog(tipo, usuarioNome, detalhe) {
    const novo = {
      id: "lg" + Date.now() + Math.random().toString(36).slice(2, 6),
      tipo,
      usuario: usuarioNome,
      detalhe: detalhe || "",
      horario: new Date().toISOString(),
    };
    const next = [...logs, novo].slice(-500); // mantém só os 500 mais recentes, pra não crescer sem limite
    setLogs(next);
    try {
      await window.storage.set("logs", JSON.stringify(next), true);
    } catch {
      // registro de log não deve travar a experiência do usuário se falhar
    }
  }

  async function persistProdutos(next) {
    setProdutos(next);
    try {
      await window.storage.set("produtos", JSON.stringify(next), true);
    } catch {
      showToast("Não foi possível sincronizar. Os dados ficaram salvos apenas neste dispositivo.", "warn");
    }
  }

  function gerarIdProduto(nome) {
    const base = nome
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "");
    let id = base || "produto";
    let n = 1;
    while (produtos.some((p) => p.id === id)) {
      id = `${base}-${n++}`;
    }
    return id;
  }

  async function salvarProduto(dados, idExistente) {
    let next;
    if (idExistente) {
      next = produtos.map((p) => (p.id === idExistente ? { ...p, ...dados } : p));
      registrarLog("produto_editado", currentUser.nome, dados.nome);
    } else {
      const id = gerarIdProduto(dados.nome);
      next = [...produtos, { id, ...dados }];
      registrarLog("produto_criado", currentUser.nome, dados.nome);
    }
    await persistProdutos(next);
    showToast(idExistente ? "Produto atualizado com sucesso." : "Produto cadastrado com sucesso.");
  }

  async function addSobra(entrada) {
    const validade = new Date();
    validade.setDate(validade.getDate() + (parseInt(entrada.validadeDias) || 2));
    const pesoInicial = parseFloat(entrada.peso) || 0;
    const nova = {
      id: "sb" + Date.now(),
      produtoId: entrada.produtoId,
      etapa: entrada.etapa,
      peso: pesoInicial,
      pesoOriginal: pesoInicial,
      registradoEm: localISO(),
      validadeDias: parseInt(entrada.validadeDias) || 2,
      validade: localISO(validade),
      observacoes: entrada.observacoes || "",
      usuario: currentUser.nome,
      loteOrigem: lote?.numero || null,
      turno: entrada.turno || turnoAtivo,
      status: "disponivel",
    };
    await persistSobras([...sobras, nova]);
    showToast("Sobra guardada com sucesso.");
  }

  async function usarSobra(id) {
    const next = sobras.map((s) => (s.id === id ? { ...s, peso: 0, status: "usada" } : s));
    await persistSobras(next);
    showToast("Sobra utilizada na produção.");
  }

  async function descartarSobra(id) {
    const sobra = sobras.find((s) => s.id === id);
    const next = sobras.map((s) => (s.id === id ? { ...s, status: "descartada" } : s));
    await persistSobras(next);
    if (sobra && sobra.peso > 0) {
      const novaPerda = {
        id: "pd" + Date.now(),
        produtoId: sobra.produtoId,
        etapa: sobra.etapa,
        peso: sobra.peso,
        motivo: "Sobra descartada (vencida ou não utilizada a tempo)",
        origem: "sobra",
        usuario: currentUser.nome,
        turno: turnoAtivo,
        horario: new Date().toISOString(),
      };
      await persistLote({ ...lote, perdas: [...(lote.perdas || []), novaPerda] });
    }
    showToast("Sobra descartada e registrada como perda.", "warn");
  }

  async function addRecheio(entrada) {
    const nova = {
      id: "r" + Date.now(),
      ...entrada,
      turno: turnoAtivo,
      usuario: currentUser.nome,
      horario: new Date().toISOString(),
    };
    await persistLote({ ...lote, recheios: [...lote.recheios, nova] });
    showToast("Recheio registrado com sucesso.");
  }

  async function addMassa(entrada) {
    const nova = {
      id: "m" + Date.now(),
      ...entrada,
      turno: turnoAtivo,
      usuario: currentUser.nome,
      horario: new Date().toISOString(),
    };
    await persistLote({ ...lote, massas: [...lote.massas, nova] });
    showToast("Massa registrada com sucesso.");
  }

  async function addModelagem(entrada) {
    const nova = {
      id: "md" + Date.now(),
      ...entrada,
      turno: turnoAtivo,
      usuario: currentUser.nome,
      horario: new Date().toISOString(),
    };
    let carrinhosAtualizados = lote.carrinhos || [];
    if (parseInt(entrada.carrinhos) > 0) {
      carrinhosAtualizados = [
        ...carrinhosAtualizados,
        {
          id: "cr" + Date.now(),
          produtoId: entrada.produtoId,
          quantidade: parseInt(entrada.carrinhos),
          observacoes: entrada.observacoes || "",
          usuario: currentUser.nome,
          turno: turnoAtivo,
          horario: new Date().toISOString(),
          status: "pendente",
        },
      ];
    }
    await persistLote({ ...lote, modelagens: [...lote.modelagens, nova], carrinhos: carrinhosAtualizados });
    showToast("Modelagem registrada com sucesso.");
  }

  async function addEmbalagem(entrada, loteAlvo) {
    const nova = {
      id: "e" + Date.now(),
      ...entrada,
      turno: turnoAtivo,
      usuario: currentUser.nome,
      horario: new Date().toISOString(),
    };
    if (loteAlvo && loteAlvo.numero !== lote.numero) {
      const atualizado = { ...loteAlvo, embalagens: [...loteAlvo.embalagens, nova] };
      try {
        await window.storage.set(loteKeyFor(new Date(atualizado.data + "T00:00:00")), JSON.stringify(atualizado), true);
      } catch {
        showToast("Não foi possível sincronizar. Tente novamente.", "warn");
      }
      setLotesAbertos((prev) => prev.map((l) => (l.numero === atualizado.numero && l.ano === atualizado.ano ? atualizado : l)));
      showToast(`Embalagem registrada no Lote ${atualizado.numero}.`);
      return atualizado;
    }
    const atualizado = { ...lote, embalagens: [...lote.embalagens, nova] };
    await persistLote(atualizado);
    showToast("Embalagem registrada com sucesso.");
    return atualizado;
  }

  async function carregarLotesAbertos() {
    try {
      const listagem = await window.storage.list("lote:", true);
      const chaves = (listagem?.keys || []).filter((k) => k !== loteKeyFor(new Date()));
      const recentes = chaves.slice(-14);
      const carregados = [];
      for (const k of recentes) {
        try {
          const res = await window.storage.get(k, true);
          const l = JSON.parse(res.value);
          if (!l.carrinhos) l.carrinhos = [];
          if (!l.finalizacoesEmbalagem) l.finalizacoesEmbalagem = [];
          if (l.status !== "fechado") carregados.push(l);
        } catch {
          // ignora lotes que não puderem ser lidos
        }
      }
      carregados.sort((a, b) => (a.data < b.data ? 1 : -1));
      setLotesAbertos(carregados);
    } catch {
      showToast("Não foi possível buscar lotes anteriores.", "warn");
    }
  }

  // Busca um lote específico pelo número (para a Embalagem, quando o lote a embalar
  // não é o lote automático do dia — ex.: produção da vespertina de ontem, embalada
  // na matutina de hoje). Não interfere na geração automática do lote do dia.
  async function buscarLotePorNumero(numeroDigitado) {
    const numeroLimpo = String(numeroDigitado || "").trim().padStart(3, "0");
    if (!numeroLimpo || numeroLimpo === "000") {
      showToast("Informe um número de lote válido.", "warn");
      return null;
    }
    const anoAtual = new Date().getFullYear();
    // Se o número informado for maior que o dia-do-ano de hoje, ele só pode ser do ano anterior
    // (lote ainda não existiria no ano corrente).
    const numeroHoje = parseInt(numeroLote(new Date()), 10);
    const ano = parseInt(numeroLimpo, 10) > numeroHoje ? anoAtual - 1 : anoAtual;
    const chave = `lote:${ano}-${numeroLimpo}`;
    try {
      const res = await window.storage.get(chave, true);
      const l = JSON.parse(res.value);
      if (!l.carrinhos) l.carrinhos = [];
      if (!l.finalizacoesEmbalagem) l.finalizacoesEmbalagem = [];
      return l;
    } catch {
      showToast(`Lote ${numeroLimpo} não encontrado.`, "warn");
      return null;
    }
  }

  async function carregarHistoricoLotes() {
    try {
      const listagem = await window.storage.list("lote:", true);
      const chaves = (listagem?.keys || []).slice(-60); // últimos ~60 lotes (cerca de 2 meses)
      const carregados = [];
      for (const k of chaves) {
        try {
          const res = await window.storage.get(k, true);
          const l = JSON.parse(res.value);
          if (!l.carrinhos) l.carrinhos = [];
          if (!l.finalizacoesEmbalagem) l.finalizacoesEmbalagem = [];
          carregados.push(l);
        } catch {
          // ignora lotes que não puderem ser lidos
        }
      }
      setHistoricoLotes(carregados);
    } catch {
      showToast("Não foi possível carregar o histórico.", "warn");
    }
  }

  // ---------- Edição de registros já lançados (correções via Histórico/Relatórios) ----------

  async function editarLancamento({ secao, loteAno, loteNumero, loteData, registroId, registroUsuario, produtoNome, etapaLabel }, alteracoes) {
    const souAdmin = currentUser.perfil === "Administrador";
    if (!souAdmin && registroUsuario !== currentUser.nome) {
      showToast("Você só pode editar os seus próprios lançamentos.", "warn");
      return false;
    }
    if (!alteracoes || Object.keys(alteracoes).length === 0) return true;

    const ehLoteAtual = lote && lote.ano === loteAno && lote.numero === loteNumero;
    let alvo = ehLoteAtual ? lote : historicoLotes.find((l) => l.ano === loteAno && l.numero === loteNumero);
    if (!alvo) {
      try {
        const res = await window.storage.get(loteKeyFor(new Date(loteData + "T00:00:00")), true);
        alvo = JSON.parse(res.value);
      } catch {
        showToast("Não foi possível localizar o lote para editar.", "warn");
        return false;
      }
    }

    const lista = alvo[secao] || [];
    const idx = lista.findIndex((r) => r.id === registroId);
    if (idx === -1) {
      showToast("Registro não encontrado — pode já ter sido alterado.", "warn");
      return false;
    }

    const camposNovos = {};
    Object.entries(alteracoes).forEach(([campo, { para }]) => {
      camposNovos[campo] = para;
    });
    const novaLista = [...lista];
    novaLista[idx] = { ...lista[idx], ...camposNovos };
    const atualizado = { ...alvo, [secao]: novaLista };

    try {
      await window.storage.set(loteKeyFor(new Date(atualizado.data + "T00:00:00")), JSON.stringify(atualizado), true);
    } catch {
      showToast("Não foi possível sincronizar a alteração. Tente novamente.", "warn");
      return false;
    }

    if (ehLoteAtual) setLote(atualizado);
    setHistoricoLotes((prev) => {
      const existe = prev.some((l) => l.ano === atualizado.ano && l.numero === atualizado.numero);
      return existe
        ? prev.map((l) => (l.ano === atualizado.ano && l.numero === atualizado.numero ? atualizado : l))
        : [...prev, atualizado];
    });

    for (const [campo, { de, para }] of Object.entries(alteracoes)) {
      const rotuloCampo = CAMPO_LABEL_AUDITORIA[campo] || campo;
      const detalhe = `Lote ${loteNumero} — ${etapaLabel}${produtoNome ? " " + produtoNome : ""} — ${rotuloCampo}: ${de ?? "-"} → ${para ?? "-"}`;
      await registrarLog("registro_editado", currentUser.nome, detalhe);
    }

    showToast("✅ Alteração salva com sucesso.");
    return true;
  }

  async function editarSobraRegistro({ registroId, registroUsuario, produtoNome }, alteracoes) {
    const souAdmin = currentUser.perfil === "Administrador";
    if (!souAdmin && registroUsuario !== currentUser.nome) {
      showToast("Você só pode editar os seus próprios lançamentos.", "warn");
      return false;
    }
    if (!alteracoes || Object.keys(alteracoes).length === 0) return true;

    const idx = sobras.findIndex((s) => s.id === registroId);
    if (idx === -1) {
      showToast("Registro não encontrado — pode já ter sido alterado.", "warn");
      return false;
    }
    const camposNovos = {};
    Object.entries(alteracoes).forEach(([campo, { para }]) => {
      camposNovos[campo] = para;
    });
    const novaLista = [...sobras];
    novaLista[idx] = { ...novaLista[idx], ...camposNovos };
    await persistSobras(novaLista);

    for (const [campo, { de, para }] of Object.entries(alteracoes)) {
      const rotuloCampo = CAMPO_LABEL_AUDITORIA[campo] || campo;
      const detalhe = `Sobra${produtoNome ? " " + produtoNome : ""} — ${rotuloCampo}: ${de ?? "-"} → ${para ?? "-"}`;
      await registrarLog("registro_editado", currentUser.nome, detalhe);
    }

    showToast("✅ Alteração salva com sucesso.");
    return true;
  }

  async function marcarCarrinhoEmbalado(id, loteAlvo, quantidadeEmbalada) {
    const alvo = loteAlvo || lote;
    const atualizado = {
      ...alvo,
      carrinhos: alvo.carrinhos.map((c) => {
        if (c.id !== id) return c;
        const restante = Math.max(0, c.quantidade - (parseInt(quantidadeEmbalada) || 0));
        return restante > 0 ? { ...c, quantidade: restante } : { ...c, quantidade: 0, status: "embalado" };
      }),
    };
    if (loteAlvo && loteAlvo.numero !== lote.numero) {
      try {
        await window.storage.set(loteKeyFor(new Date(atualizado.data + "T00:00:00")), JSON.stringify(atualizado), true);
      } catch {
        showToast("Não foi possível sincronizar. Tente novamente.", "warn");
      }
      setLotesAbertos((prev) => prev.map((l) => (l.numero === atualizado.numero && l.ano === atualizado.ano ? atualizado : l)));
      return atualizado;
    }
    await persistLote(atualizado);
    return atualizado;
  }

  async function finalizarEmbalagemProduto(payload, loteAlvo) {
    const alvo = loteAlvo || lote;
    const diferenca = payload.esperado - payload.embalado;
    const registro = {
      produtoId: payload.produtoId,
      esperado: payload.esperado,
      embalado: payload.embalado,
      diferenca,
      fechado: !payload.temCarrinhosPendentes,
      usuario: currentUser.nome,
      horario: new Date().toISOString(),
    };
    const outros = (alvo.finalizacoesEmbalagem || []).filter((f) => f.produtoId !== payload.produtoId);
    const atualizado = { ...alvo, finalizacoesEmbalagem: [...outros, registro] };
    if (loteAlvo && loteAlvo.numero !== lote.numero) {
      try {
        await window.storage.set(loteKeyFor(new Date(atualizado.data + "T00:00:00")), JSON.stringify(atualizado), true);
      } catch {
        showToast("Não foi possível sincronizar. Tente novamente.", "warn");
      }
      setLotesAbertos((prev) => prev.map((l) => (l.numero === atualizado.numero && l.ano === atualizado.ano ? atualizado : l)));
      showToast(registro.fechado ? "Embalagem finalizada." : "Finalizado por enquanto — ainda há carrinhos pendentes.");
      return atualizado;
    }
    await persistLote(atualizado);
    showToast(registro.fechado ? "Embalagem finalizada." : "Finalizado por enquanto — ainda há carrinhos pendentes.");
    return atualizado;
  }

  async function fecharLote(resumo) {
    const atualizado = {
      ...lote,
      status: "fechado",
      fechamento: {
        usuario: currentUser.nome,
        horario: new Date().toISOString(),
        resumo,
      },
    };
    await persistLote(atualizado);
    registrarLog("fechamento_lote", currentUser.nome, `Lote ${lote.numero} (${lote.data})`);
    showToast(`Lote ${lote.numero} fechado com sucesso.`);
    return atualizado;
  }

  // Reabertura de lote fechado — somente Administrador. Reutiliza o mesmo lote
  // (mesmo número, mesmos dados); apenas destrava os lançamentos para correção.
  async function reabrirLote() {
    if (currentUser.perfil !== "Administrador") {
      showToast("Somente um Administrador pode reabrir um lote fechado.", "warn");
      return false;
    }
    if (lote.status !== "fechado") return false;
    const eventoReabertura = { usuario: currentUser.nome, horario: new Date().toISOString() };
    const atualizado = {
      ...lote,
      status: "aberto",
      reaberturas: [...(lote.reaberturas || []), eventoReabertura],
    };
    await persistLote(atualizado);
    registrarLog("lote_reaberto", currentUser.nome, `Lote ${lote.numero} (${lote.data})`);
    showToast(`Lote ${lote.numero} reaberto para correções.`);
    return true;
  }

  async function handleLogin(usuario, senha) {
    const u = usuario.trim().toLowerCase();
    const s = senha.trim();
    const found = users.find((x) => x.usuario.toLowerCase() === u);
    if (!found) return { ok: false, msg: "Usuário ou senha incorretos." };
    const hash = await hashSenha(s, found.salt);
    if (hash !== found.senhaHash) return { ok: false, msg: "Usuário ou senha incorretos." };
    if (found.status !== "ativo") return { ok: false, msg: "Cadastro ainda não aprovado ou está inativo." };
    setCurrentUser(found);
    setView("app");
    registrarLog("login", found.nome, `usuário: ${found.usuario}`);
    return { ok: true };
  }

  async function handleSignup({ nome, usuario, senha }) {
    if (users.some((x) => x.usuario === usuario) || requests.some((x) => x.usuario === usuario)) {
      return { ok: false, msg: "Esse nome de usuário já está em uso ou aguardando aprovação." };
    }
    const salt = gerarSaltHex();
    const senhaHash = await hashSenha(senha, salt);
    const novo = { id: "r" + Date.now(), nome, usuario, salt, senhaHash, status: "pendente", data: new Date().toISOString() };
    await persistRequests([...requests, novo]);
    return { ok: true };
  }

  async function approveRequest(reqId, approve) {
    const req = requests.find((r) => r.id === reqId);
    if (!req) return;
    if (approve) {
      const novoUsuario = { id: "u" + Date.now(), nome: req.nome, usuario: req.usuario, salt: req.salt, senhaHash: req.senhaHash, perfil: "Produção", status: "ativo" };
      await persistUsers([...users, novoUsuario]);
      registrarLog("cadastro_aprovado", currentUser.nome, `Aprovou ${req.nome} (@${req.usuario})`);
      showToast(`${req.nome} aprovado como usuário.`);
    } else {
      registrarLog("cadastro_recusado", currentUser.nome, `Recusou ${req.nome} (@${req.usuario})`);
      showToast(`Solicitação de ${req.nome} recusada.`, "warn");
    }
    await persistRequests(requests.filter((r) => r.id !== reqId));
  }

  function logout() {
    if (currentUser) registrarLog("logout", currentUser.nome, `usuário: ${currentUser.usuario}`);
    setCurrentUser(null);
    setProfileOpen(false);
    setView("login");
    setTab("home");
    setScreen("none");
  }

  if (booting) return <BootScreen />;
  if (view === "login") return <LoginScreen onLogin={handleLogin} onGoSignup={() => setView("signup")} />;
  if (view === "signup") return <SignupScreen onSignup={handleSignup} onBack={() => setView("login")} />;

  return (
    <div className="min-h-screen flex flex-col" style={{ background: C.gray100 }}>
      <Header
        user={currentUser}
        profileOpen={profileOpen}
        setProfileOpen={setProfileOpen}
        onLogout={logout}
        onOpenPlanejamento={() => {
          setScreen("planejamento");
          setProfileOpen(false);
        }}
        onOpenSobras={() => {
          setScreen("sobras");
          setProfileOpen(false);
        }}
        onOpenFechamento={() => {
          setScreen("fechamento");
          setProfileOpen(false);
        }}
        onOpenAuditoria={() => {
          setScreen("auditoria");
          setProfileOpen(false);
        }}
        onOpenProdutos={() => {
          setScreen("produtos");
          setProfileOpen(false);
        }}
        onOpenUsuarios={() => {
          setScreen("usuarios");
          setProfileOpen(false);
        }}
        sobrasAlerta={sobras.filter((s) => s.status === "disponivel" && statusSobra(s).dias <= 2).length}
        requests={requests}
        lote={lote}
        turnoAtivo={turnoAtivo}
        setTurnoAtivo={setTurnoAtivo}
      />
      {toast && <Toast toast={toast} />}
      {screen === "planejamento" ? (
        <PlanejamentoScreen
          user={currentUser}
          produtos={produtos}
          planos={planos}
          onSave={async (plano) => {
            const outros = planos.filter((p) => p.semana !== plano.semana);
            await persistPlanos([...outros, plano]);
            showToast("Planejamento salvo com sucesso.");
          }}
          onBack={() => setScreen("none")}
        />
      ) : screen === "sobras" ? (
        <SobrasScreen
          produtos={produtos}
          sobras={sobras}
          onAdd={addSobra}
          onUsar={usarSobra}
          onDescartar={descartarSobra}
          onBack={() => setScreen("none")}
        />
      ) : screen === "fechamento" ? (
        <FechamentoScreen
          user={currentUser}
          produtos={produtos}
          lote={lote}
          planos={planos}
          sobras={sobras}
          onFechar={fecharLote}
          onReabrir={reabrirLote}
          onBack={() => setScreen("none")}
        />
      ) : screen === "auditoria" ? (
        <AuditoriaScreen
          produtos={produtos}
          users={users}
          logs={logs}
          lote={lote}
          historicoLotes={historicoLotes}
          onCarregarHistorico={carregarHistoricoLotes}
          onBack={() => setScreen("none")}
        />
      ) : screen === "produtos" ? (
        <ProdutosScreen produtos={produtos} onSalvar={salvarProduto} onBack={() => setScreen("none")} />
      ) : screen === "usuarios" ? (
        <UsuariosScreen
          currentUser={currentUser}
          users={users}
          requests={requests}
          onSalvar={salvarUsuario}
          onCriar={criarUsuarioDireto}
          onResetSenha={redefinirSenhaUsuario}
          onAlternarStatus={alternarStatusUsuario}
          onExcluir={excluirUsuario}
          onAprovar={approveRequest}
          onBack={() => setScreen("none")}
        />
      ) : screen === "dashboard" ? (
        <DashboardScreen
          produtos={produtos}
          lote={lote}
          planos={planos}
          historicoLotes={historicoLotes}
          onCarregarHistorico={carregarHistoricoLotes}
          onOpenPerdas={() => setScreen("perdas")}
          onBack={() => setScreen("none")}
        />
      ) : screen === "perdas" ? (
        <PerdasScreen
          produtos={produtos}
          lote={lote}
          historicoLotes={historicoLotes}
          onCarregarHistorico={carregarHistoricoLotes}
          onBack={() => setScreen("none")}
        />
      ) : (
        <>
          <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
            <BarraDataTrabalho lote={lote} dataTrabalho={dataTrabalho} trocando={trocandoData} onTrocar={trocarDataTrabalho} />
            {tab === "home" && (
              <HomeTab
                user={currentUser}
                requests={requests}
                onApprove={approveRequest}
                sobras={sobras}
                onOpenSobras={() => setScreen("sobras")}
                onOpenDashboard={() => setScreen("dashboard")}
                onOpenPerdas={() => setScreen("perdas")}
                produtos={produtos}
                lote={lote}
                planos={planos}
                turnoAtivo={turnoAtivo}
                onIrRelatorios={() => setTab("relatorios")}
              />
            )}
            {tab === "recheio" && (
              <RecheioTab
                produtos={produtos}
                planos={planos}
                lote={lote}
                turnoAtivo={turnoAtivo}
                onAdd={addRecheio}
                sobras={sobras}
                onUsarSobra={usarSobra}
                onOpenPerdas={() => setScreen("perdas")}
              />
            )}
            {tab === "massa" && (
              <MassaTab
                produtos={produtos}
                planos={planos}
                lote={lote}
                turnoAtivo={turnoAtivo}
                onAdd={addMassa}
                sobras={sobras}
                onUsarSobra={usarSobra}
                onOpenPerdas={() => setScreen("perdas")}
              />
            )}
            {tab === "modelagem" && (
              <ModelagemTab
                produtos={produtos}
                lote={lote}
                turnoAtivo={turnoAtivo}
                onAdd={addModelagem}
                onAddSobra={addSobra}
                sobras={sobras}
                onOpenPerdas={() => setScreen("perdas")}
              />
            )}
            {tab === "embalagem" && (
              <EmbalagemTab
                produtos={produtos}
                lote={lote}
                turnoAtivo={turnoAtivo}
                onAdd={addEmbalagem}
                lotesAbertos={lotesAbertos}
                onCarregarLotesAbertos={carregarLotesAbertos}
                onBuscarLotePorNumero={buscarLotePorNumero}
                onMarcarCarrinhoEmbalado={marcarCarrinhoEmbalado}
                onFinalizarEmbalagem={finalizarEmbalagemProduto}
                onOpenPerdas={() => setScreen("perdas")}
              />
            )}
            {tab === "relatorios" && (
              <RelatoriosTab
                user={currentUser}
                produtos={produtos}
                planos={planos}
                lote={lote}
                historicoLotes={historicoLotes}
                onCarregarHistorico={carregarHistoricoLotes}
                sobras={sobras}
                onEditarLancamento={editarLancamento}
                onEditarSobra={editarSobraRegistro}
              />
            )}
            {tab !== "home" && tab !== "recheio" && tab !== "massa" && tab !== "modelagem" && tab !== "embalagem" && tab !== "relatorios" && <ComingSoon label={tab} />}
          </main>
          <BottomNav tab={tab} setTab={setTab} />
        </>
      )}
    </div>
  );
}

