// ---------- Login ----------

function LoginScreen({ onLogin, onGoSignup }) {
  const [usuario, setUsuario] = useState("");
  const [senha, setSenha] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState("");
  const [helpMsg, setHelpMsg] = useState("");
  const [verificando, setVerificando] = useState(false);
  const lockRef = useRef(false);

  async function submit() {
    if (lockRef.current) return;
    lockRef.current = true;
    setError("");
    setVerificando(true);
    try {
      const r = await onLogin(usuario, senha);
      if (!r.ok) setError(r.msg);
    } finally {
      lockRef.current = false;
      setVerificando(false);
    }
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-6" style={{ background: C.gray100 }}>
      <div className="w-full max-w-sm">
        <div className="flex flex-col items-center mb-8">
          <Seal size={56} />
          <div className="mt-3 font-bold text-xl tracking-tight" style={{ color: C.black }}>TANÊSHIRO</div>
          <div className="text-[11px] tracking-[0.25em] font-medium" style={{ color: C.gray500 }}>PRODUÇÃO</div>
        </div>

        <div className="rounded-2xl p-6 space-y-4" style={{ background: C.white, boxShadow: "0 1px 2px rgba(0,0,0,0.04), 0 8px 24px rgba(0,0,0,0.06)" }}>
          <Field icon={<User size={16} />} placeholder="Usuário" value={usuario} onChange={setUsuario} />
          <Field
            icon={<Lock size={16} />}
            placeholder="Senha"
            value={senha}
            onChange={setSenha}
            type={showPass ? "text" : "password"}
            rightIcon={
              <button type="button" onClick={() => setShowPass((s) => !s)} className="text-gray-400">
                {showPass ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            }
          />
          {error && <div className="text-sm rounded-lg px-3 py-2" style={{ background: C.redSoft, color: C.redDark }}>{error}</div>}

          <button type="button" onClick={submit} disabled={verificando} className="w-full rounded-xl py-3 font-semibold text-white text-sm" style={{ background: C.red, opacity: verificando ? 0.7 : 1 }}>
            {verificando ? "Verificando..." : "Entrar"}
          </button>

          <div className="flex items-center justify-between text-xs pt-1">
            <button type="button" onClick={onGoSignup} className="font-medium" style={{ color: C.red }}>
              Solicitar cadastro
            </button>
            <button type="button" onClick={() => setHelpMsg("Fale com o Administrador para redefinir sua senha.")} className="text-gray-400">
              Esqueci minha senha
            </button>
          </div>
          {helpMsg && <div className="text-xs text-center" style={{ color: C.gray500 }}>{helpMsg}</div>}
        </div>

        <div className="text-center text-[11px] mt-6" style={{ color: C.gray500 }}>
          Acesso restrito à equipe TanêShiro
        </div>
      </div>
    </div>
  );
}

// ---------- Signup ----------

function SignupScreen({ onSignup, onBack }) {
  const [nome, setNome] = useState("");
  const [usuario, setUsuario] = useState("");
  const [senha, setSenha] = useState("");
  const [confirmar, setConfirmar] = useState("");
  const [error, setError] = useState("");
  const [done, setDone] = useState(false);

  async function submit() {
    setError("");
    if (!nome || !usuario || !senha) return setError("Preencha todos os campos.");
    if (senha !== confirmar) return setError("As senhas não coincidem.");
    const r = await onSignup({ nome: nome.trim(), usuario: usuario.trim(), senha });
    if (!r.ok) return setError(r.msg);
    setDone(true);
  }

  if (done) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center px-6 text-center" style={{ background: C.gray100 }}>
        <div className="rounded-full p-4 mb-4" style={{ background: C.redSoft }}>
          <Clock size={28} color={C.red} />
        </div>
        <div className="font-bold text-lg" style={{ color: C.black }}>Aguardando aprovação</div>
        <div className="text-sm mt-2 max-w-xs" style={{ color: C.gray500 }}>
          O Administrador foi notificado. Você poderá entrar assim que sua solicitação for aprovada.
        </div>
        <button onClick={onBack} className="mt-6 text-sm font-semibold" style={{ color: C.red }}>Voltar ao login</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-6" style={{ background: C.gray100 }}>
      <div className="w-full max-w-sm">
        <button onClick={onBack} className="flex items-center gap-1 text-sm mb-6" style={{ color: C.gray500 }}>
          <ArrowLeft size={16} /> Voltar
        </button>
        <div className="mb-6">
          <div className="font-bold text-xl" style={{ color: C.black }}>Solicitar cadastro</div>
          <div className="text-sm" style={{ color: C.gray500 }}>Um administrador vai revisar seu acesso.</div>
        </div>
        <div className="rounded-2xl p-6 space-y-4" style={{ background: C.white, boxShadow: "0 1px 2px rgba(0,0,0,0.04), 0 8px 24px rgba(0,0,0,0.06)" }}>
          <Field icon={<User size={16} />} placeholder="Nome completo" value={nome} onChange={setNome} />
          <Field icon={<User size={16} />} placeholder="Usuário" value={usuario} onChange={setUsuario} />
          <Field icon={<Lock size={16} />} placeholder="Senha" type="password" value={senha} onChange={setSenha} />
          <Field icon={<Lock size={16} />} placeholder="Confirmar senha" type="password" value={confirmar} onChange={setConfirmar} />
          {error && <div className="text-sm rounded-lg px-3 py-2" style={{ background: C.redSoft, color: C.redDark }}>{error}</div>}
          <button type="button" onClick={submit} className="w-full rounded-xl py-3 font-semibold text-white text-sm" style={{ background: C.red }}>
            Enviar solicitação
          </button>
        </div>
      </div>
    </div>
  );
}

function Field({ icon, rightIcon, ...props }) {
  return (
    <div className="flex items-center gap-2 rounded-xl px-3 py-2.5" style={{ background: C.gray100 }}>
      <span style={{ color: C.gray500 }}>{icon}</span>
      <input
        autoCapitalize="none"
        autoCorrect="off"
        autoComplete="off"
        spellCheck="false"
        {...props}
        onChange={(e) => props.onChange(e.target.value)}
        className="flex-1 bg-transparent outline-none text-sm"
        style={{ color: C.black }}
      />
      {rightIcon}
    </div>
  );
}

