// Modal genérico para corrigir um registro já lançado (recheio, massa,
// modelagem, embalagem, sobra ou perda). Só é aberto a partir do
// Histórico/Relatórios — nunca a partir das telas de lançamento.
function EditarRegistroModal({ titulo, subtitulo, campos, valores, onSalvar, onFechar }) {
  const [form, setForm] = useState(() => ({ ...valores }));
  const [salvando, setSalvando] = useState(false);

  function setCampo(key, val) {
    setForm((f) => ({ ...f, [key]: val }));
  }

  async function confirmar() {
    if (salvando) return;
    setSalvando(true);
    try {
      const alterados = {};
      campos.forEach((c) => {
        const antigo = valores[c.key];
        const novo = c.tipo === "numero" ? parseFloat(form[c.key]) || 0 : form[c.key] ?? "";
        if (String(antigo ?? "") !== String(novo ?? "")) {
          alterados[c.key] = { de: antigo, para: novo };
        }
      });
      if (Object.keys(alterados).length === 0) {
        onFechar();
        return;
      }
      await onSalvar(alterados);
    } finally {
      setSalvando(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center" style={{ background: "rgba(22,19,17,0.5)" }} onClick={onFechar}>
      <div
        className="w-full max-w-md rounded-t-2xl sm:rounded-2xl p-5 max-h-[85vh] overflow-y-auto"
        style={{ background: C.white }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-1">
          <div className="font-bold text-base" style={{ color: C.black }}>✏️ Editar registro</div>
          <button onClick={onFechar} aria-label="Fechar" className="p-1 rounded-full" style={{ background: C.gray100 }}>
            <X size={16} color={C.gray500} />
          </button>
        </div>
        <div className="text-sm mb-1" style={{ color: C.gray900 }}>{titulo}</div>
        {subtitulo && <div className="text-xs mb-4" style={{ color: C.gray500 }}>{subtitulo}</div>}

        <div className="space-y-3 mb-4">
          {campos.map((c) => (
            <div key={c.key}>
              <label className="text-xs font-semibold" style={{ color: C.gray500 }}>
                {c.label}
                {c.unidade ? ` (${c.unidade})` : ""}
              </label>
              {c.tipo === "texto_longo" ? (
                <textarea
                  value={form[c.key] ?? ""}
                  onChange={(e) => setCampo(c.key, e.target.value)}
                  rows={2}
                  className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1 resize-none"
                  style={{ background: C.gray100, color: C.black }}
                />
              ) : (
                <input
                  type={c.tipo === "numero" ? "number" : "text"}
                  step={c.tipo === "numero" ? "0.1" : undefined}
                  min={c.tipo === "numero" ? "0" : undefined}
                  value={form[c.key] ?? ""}
                  onChange={(e) => setCampo(c.key, e.target.value)}
                  className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1"
                  style={{ background: C.gray100, color: C.black }}
                />
              )}
            </div>
          ))}
        </div>

        <div className="flex gap-2">
          <button
            onClick={onFechar}
            className="flex-1 rounded-xl py-2.5 text-sm font-semibold"
            style={{ background: C.gray100, color: C.gray900 }}
          >
            Cancelar
          </button>
          <button
            onClick={confirmar}
            disabled={salvando}
            className="flex-1 flex items-center justify-center gap-1.5 rounded-xl py-2.5 text-sm font-semibold"
            style={{ background: C.red, color: C.white, opacity: salvando ? 0.7 : 1 }}
          >
            <Save size={14} /> {salvando ? "Salvando..." : "Salvar alterações"}
          </button>
        </div>
      </div>
    </div>
  );
}

// Configuração de quais campos cada tipo de lançamento permite corrigir.
// (usada só pela edição no Histórico/Relatórios — não afeta as telas de lançamento)
function camposEditaveisPara(item) {
  if (item.tipo === "recheio" || item.tipo === "massa") {
    return [
      { key: "peso", label: "Peso produzido", unidade: "kg", tipo: "numero" },
      { key: "perda", label: "Perda", unidade: "kg", tipo: "numero" },
      { key: "observacoes", label: "Observações", tipo: "texto_longo" },
    ];
  }
  if (item.tipo === "modelagem") {
    const campos = [];
    if (item.registro.massaUtilizada != null) campos.push({ key: "massaUtilizada", label: "Massa utilizada", unidade: "kg", tipo: "numero" });
    if (item.registro.recheioUtilizado != null) campos.push({ key: "recheioUtilizado", label: "Recheio utilizado", unidade: "kg", tipo: "numero" });
    if (item.registro.catupiryUtilizado != null) campos.push({ key: "catupiryUtilizado", label: "Catupiry utilizado", unidade: "kg", tipo: "numero" });
    if (item.registro.farinhaUtilizada != null) campos.push({ key: "farinhaUtilizada", label: "Farinha (empanamento)", unidade: "kg", tipo: "numero" });
    campos.push({ key: "perda", label: "Perda", unidade: "kg", tipo: "numero" });
    campos.push({ key: "observacoes", label: "Observações", tipo: "texto_longo" });
    return campos;
  }
  if (item.tipo === "embalagem") {
    return [
      { key: "quantidadeEmbalada", label: "Quantidade embalada", unidade: "un", tipo: "numero" },
      { key: "perda", label: "Perda", unidade: "un", tipo: "numero" },
      { key: "observacoes", label: "Observações", tipo: "texto_longo" },
    ];
  }
  if (item.tipo === "perda") {
    return [
      { key: "peso", label: "Peso descartado", unidade: "kg", tipo: "numero" },
      { key: "motivo", label: "Motivo", tipo: "texto_longo" },
    ];
  }
  // sobra
  return [
    { key: "peso", label: "Peso em estoque", unidade: "kg", tipo: "numero" },
    { key: "observacoes", label: "Observações", tipo: "texto_longo" },
  ];
}

const TIPO_LABEL_LANCAMENTO = { recheio: "Recheio", massa: "Massa", modelagem: "Modelagem", embalagem: "Embalagem", perda: "Perda (sobra descartada)", sobra: "Sobra em estoque" };

function RelatoriosTab({ user, produtos, planos, lote, historicoLotes, onCarregarHistorico, sobras = [], onEditarLancamento, onEditarSobra }) {
  const [tipo, setTipo] = useState("diario"); // diario | semanal | mensal
  const [dataRef, setDataRef] = useState(localISO());
  const [carregando, setCarregando] = useState(true);
  const [mensagem, setMensagem] = useState("");
  const [mostrarLancamentos, setMostrarLancamentos] = useState(false);
  const [editando, setEditando] = useState(null); // item selecionado para edição

  useEffect(() => {
    (async () => {
      await onCarregarHistorico();
      setCarregando(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const ativos = produtos.filter((p) => p.status === "ativo");
  const todosLotes = [...historicoLotes.filter((l) => !(l.ano === lote.ano && l.numero === lote.numero)), lote];

  function dentroDoPeriodo(dataStr) {
    if (tipo === "diario") return dataStr === dataRef;
    if (tipo === "semanal") {
      const seg = segundaFeiraDe(dataRef);
      const dom = diasDaSemana(seg)[6];
      return dataStr >= seg && dataStr <= dom;
    }
    return dataStr.slice(0, 7) === dataRef.slice(0, 7);
  }

  const lotesRelatorio = todosLotes.filter((l) => dentroDoPeriodo(l.data)).sort((a, b) => (a.data < b.data ? -1 : 1));

  const nomeProduto = (id) => produtos.find((p) => p.id === id)?.nome || id;
  const souAdmin = user.perfil === "Administrador";

  // ---- Lançamentos do período, para a edição/correção (só aparece aqui, no Histórico/Relatórios) ----
  const lancamentosEditaveis = [];
  lotesRelatorio.forEach((l) => {
    l.recheios.forEach((r) => lancamentosEditaveis.push({ tipo: "recheio", secao: "recheios", loteAno: l.ano, loteNumero: l.numero, loteData: l.data, registro: r }));
    l.massas.forEach((m) => lancamentosEditaveis.push({ tipo: "massa", secao: "massas", loteAno: l.ano, loteNumero: l.numero, loteData: l.data, registro: m }));
    l.modelagens.forEach((md) => lancamentosEditaveis.push({ tipo: "modelagem", secao: "modelagens", loteAno: l.ano, loteNumero: l.numero, loteData: l.data, registro: md }));
    l.embalagens.forEach((e) => lancamentosEditaveis.push({ tipo: "embalagem", secao: "embalagens", loteAno: l.ano, loteNumero: l.numero, loteData: l.data, registro: e }));
    (l.perdas || []).forEach((p) => lancamentosEditaveis.push({ tipo: "perda", secao: "perdas", loteAno: l.ano, loteNumero: l.numero, loteData: l.data, registro: p }));
  });
  sobras.filter((s) => dentroDoPeriodo((s.registradoEm || "").slice(0, 10))).forEach((s) => lancamentosEditaveis.push({ tipo: "sobra", secao: "sobras", registro: s }));
  lancamentosEditaveis.sort((a, b) => ((b.registro.horario || b.registro.registradoEm || "") < (a.registro.horario || a.registro.registradoEm || "") ? -1 : 1));

  function podeEditar(item) {
    return souAdmin || item.registro.usuario === user.nome;
  }

  function resumoLancamento(item) {
    const r = item.registro;
    if (item.tipo === "recheio" || item.tipo === "massa") return `${r.peso}kg${r.perda > 0 ? ` · perda ${r.perda}kg` : ""}`;
    if (item.tipo === "modelagem") {
      const partes = [];
      if (r.massaUtilizada != null) partes.push(`massa ${r.massaUtilizada}kg`);
      if (r.recheioUtilizado != null) partes.push(`recheio ${r.recheioUtilizado}kg`);
      if (r.farinhaUtilizada != null) partes.push(`farinha ${r.farinhaUtilizada}kg`);
      return partes.join(" · ") || "-";
    }
    if (item.tipo === "embalagem") return `${r.quantidadeEmbalada}un.${r.perda > 0 ? ` · perda ${r.perda}un.` : ""}`;
    if (item.tipo === "perda") return `${r.peso}kg — ${ETAPA_PERDA_LABEL["sobra-" + r.etapa] || r.motivo || ""}`;
    return `${r.peso}kg em estoque`;
  }

  async function salvarEdicao(alteracoes) {
    if (!editando) return;
    let ok;
    if (editando.tipo === "sobra") {
      ok = await onEditarSobra(
        { registroId: editando.registro.id, registroUsuario: editando.registro.usuario, produtoNome: nomeProduto(editando.registro.produtoId) },
        alteracoes
      );
    } else {
      ok = await onEditarLancamento(
        {
          secao: editando.secao,
          loteAno: editando.loteAno,
          loteNumero: editando.loteNumero,
          loteData: editando.loteData,
          registroId: editando.registro.id,
          registroUsuario: editando.registro.usuario,
          produtoNome: nomeProduto(editando.registro.produtoId),
          etapaLabel: TIPO_LABEL_LANCAMENTO[editando.tipo],
        },
        alteracoes
      );
    }
    if (ok) setEditando(null);
  }

  function qtdEsperadaAgg(produto) {
    let total = 0;
    lotesRelatorio.forEach((l) => {
      if (produto.pesoRecheio > 0) {
        const peso = l.recheios.filter((r) => r.produtoId === produto.id).reduce((s, r) => s + (parseFloat(r.peso) || 0), 0);
        total += (peso * 1000) / produto.pesoRecheio;
      } else if (produto.pesoMassa > 0) {
        const peso = l.massas.filter((m) => m.produtoId === produto.id).reduce((s, m) => s + (parseFloat(m.peso) || 0), 0);
        total += (peso * 1000) / produto.pesoMassa;
      }
    });
    return Math.round(total);
  }
  function embaladoAgg(produtoId, turno) {
    return lotesRelatorio.reduce((s, l) => s + l.embalagens.filter((e) => e.produtoId === produtoId && (turno == null || e.turno === turno)).reduce((s2, e) => s2 + (parseInt(e.quantidadeEmbalada) || 0), 0), 0);
  }
  function perdaProdutoAgg(produtoId) {
    return lotesRelatorio.reduce((s, l) => {
      const r = l.recheios.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      const m = l.massas.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      const md = l.modelagens.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      return s + r + m + md;
    }, 0);
  }

  const porProduto = ativos
    .map((p) => ({ produto: p, esperado: qtdEsperadaAgg(p), embalado: embaladoAgg(p.id, null), perdaKg: perdaProdutoAgg(p.id) }))
    .filter((x) => x.esperado > 0 || x.embalado > 0 || x.perdaKg > 0);

  const totalEsperado = porProduto.reduce((s, x) => s + x.esperado, 0);
  const totalEmbalado = porProduto.reduce((s, x) => s + x.embalado, 0);
  const rendimento = statusRendimento(totalEmbalado, totalEsperado);

  const perdaRecheioKg = lotesRelatorio.reduce((s, l) => s + l.recheios.reduce((s2, r) => s2 + (parseFloat(r.perda) || 0), 0), 0);
  const perdaMassaKg = lotesRelatorio.reduce((s, l) => s + l.massas.reduce((s2, m) => s2 + (parseFloat(m.perda) || 0), 0), 0);
  const perdaModelagemKg = lotesRelatorio.reduce((s, l) => s + l.modelagens.reduce((s2, m) => s2 + (parseFloat(m.perda) || 0), 0), 0);
  const perdaEmbalagemKg = lotesRelatorio.reduce((s, l) => s + l.embalagens.reduce((s2, e) => s2 + (parseFloat(e.perda) || 0), 0), 0);
  const perdaSobrasKg = lotesRelatorio.reduce((s, l) => s + (l.perdas || []).reduce((s2, p) => s2 + (parseFloat(p.peso) || 0), 0), 0);

  const planejadoRecheioKg = planos.reduce((s, p) => {
    return (
      s +
      Object.entries(p.dias || {})
        .filter(([d]) => dentroDoPeriodo(d))
        .reduce((s2, [, dia]) => {
          const itens = [...(dia.matutino || []), ...(dia.vespertino || [])];
          return s2 + itens.reduce((s3, it) => s3 + (parseFloat(it.quantidade) || 0), 0);
        }, 0)
    );
  }, 0);
  // Produzido (Recheio): só o peso de recheio efetivamente produzido — comparável ao Planejado (Recheio).
  const produzidoRecheioKg = lotesRelatorio.reduce((s, l) => s + l.recheios.reduce((s2, r) => s2 + (parseFloat(r.peso) || 0), 0), 0);
  const produzidoMassaKg = lotesRelatorio.reduce((s, l) => s + l.massas.reduce((s2, m) => s2 + (parseFloat(m.peso) || 0), 0), 0);
  // Farinha (empanamento) e Catupiry são componentes adicionados na Modelagem, que também compõem o peso final.
  const produzidoFarinhaKg = lotesRelatorio.reduce((s, l) => s + l.modelagens.reduce((s2, m) => s2 + (parseFloat(m.farinhaUtilizada) || 0), 0), 0);
  const produzidoCatupiryKg = lotesRelatorio.reduce((s, l) => s + l.modelagens.reduce((s2, m) => s2 + (parseFloat(m.catupiryUtilizado) || 0), 0), 0);
  // Produzido Total: peso total efetivamente produzido (recheio + massa + farinha/outros componentes).
  const produzidoTotalKg = produzidoRecheioKg + produzidoMassaKg + produzidoFarinhaKg + produzidoCatupiryKg;

  const embMatutino = tipo === "diario" ? ativos.reduce((s, p) => s + embaladoAgg(p.id, "matutino"), 0) : null;
  const embVespertino = tipo === "diario" ? ativos.reduce((s, p) => s + embaladoAgg(p.id, "vespertino"), 0) : null;

  const responsaveis = [...new Set(lotesRelatorio.filter((l) => l.status === "fechado").map((l) => l.fechamento?.usuario).filter(Boolean))];

  const tituloTipo = tipo === "diario" ? "Relatório Diário" : tipo === "semanal" ? "Relatório Semanal" : "Relatório Mensal";
  const periodoTexto =
    tipo === "diario"
      ? fmtData(dataRef)
      : tipo === "semanal"
      ? `${fmtData(segundaFeiraDe(dataRef))} a ${fmtData(diasDaSemana(segundaFeiraDe(dataRef))[6])}`
      : new Date(dataRef + "-01T00:00:00").toLocaleDateString("pt-BR", { month: "long", year: "numeric" });

  function gerarHtmlRelatorio() {
    const linhasProduto = porProduto
      .map(
        (x) =>
          `<tr><td>${x.produto.nome}</td><td style="text-align:right">${x.embalado}</td><td style="text-align:right">${x.esperado}</td><td style="text-align:right">${x.perdaKg.toFixed(1)}kg</td></tr>`
      )
      .join("");
    const turnoHtml =
      tipo === "diario"
        ? `<div class="bloco"><div class="rotulo">PRODUÇÃO POR TURNO</div><div>☀️ Matutino: <strong>${embMatutino}</strong> un. · 🌙 Vespertino: <strong>${embVespertino}</strong> un.</div></div>`
        : "";

    const dadosImagem = {
      titulo: tituloTipo,
      periodo: periodoTexto,
      lotes: lotesRelatorio.length > 0 ? lotesRelatorio.map((l) => l.numero).join(", ") : "nenhum",
      esperado: totalEsperado,
      embalado: totalEmbalado,
      rendimentoTexto: `${rendimento.emoji} ${rendimento.label}${rendimento.pct != null ? ` (${rendimento.pct.toFixed(1)}%)` : ""}`,
      perdasTexto: `Recheio ${perdaRecheioKg.toFixed(1)}kg · Massa ${perdaMassaKg.toFixed(1)}kg · Modelagem ${perdaModelagemKg.toFixed(1)}kg · Embalagem ${perdaEmbalagemKg.toFixed(1)}kg${perdaSobrasKg > 0 ? ` · Sobras ${perdaSobrasKg.toFixed(1)}kg` : ""}`,
      produtos: porProduto.map((x) => ({ nome: x.produto.nome, embalado: x.embalado, esperado: x.esperado, perda: x.perdaKg.toFixed(1) })),
      geradoPor: `Gerado por ${user.nome} em ${new Date().toLocaleString("pt-BR")}`,
    };
    const dadosImagemJson = JSON.stringify(dadosImagem).replace(/</g, "\\u003c");

    return `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="utf-8"><title>${tituloTipo} — TANÊSHIRO</title>
<style>
  body { font-family: -apple-system, "Helvetica Neue", Arial, sans-serif; max-width: 640px; margin: 24px auto; padding: 0 16px; color: #161311; }
  .cabecalho { display:flex; align-items:center; gap:10px; margin-bottom:16px; }
  .selo { width:40px; height:40px; border-radius:50%; background:#C8161D; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:bold; }
  .titulo { font-weight:bold; font-size:14px; }
  .sub { font-size:10px; color:#8A837C; letter-spacing:1px; }
  h1 { font-size:20px; margin:16px 0 2px; }
  .periodo { color:#8A837C; font-size:13px; margin-bottom:4px; }
  .bloco { margin-top:18px; }
  .rotulo { font-size:11px; font-weight:600; color:#8A837C; margin-bottom:4px; }
  table { width:100%; border-collapse:collapse; font-size:13px; margin-top:6px; }
  th, td { text-align:left; padding:6px 4px; border-bottom:1px solid #E8E4DF; }
  .botoes { margin: 20px 0; display:flex; gap:10px; flex-wrap:wrap; }
  .botoes button { flex:1; min-width:140px; text-align:center; padding:12px; border-radius:8px; border:none; font-weight:600; font-size:13px; cursor:pointer; }
  .btn-primario { background:#C8161D; color:#fff; }
  .btn-secundario { background:#F5F3F0; color:#161311; }
  .status { font-size:12px; color:#8A837C; text-align:center; margin-top:6px; min-height:16px; }
  @media print { .botoes, .status, #canvasWrap { display:none; } }
</style></head>
<body>
  <div class="botoes no-print">
    <button class="btn-primario" onclick="window.print()">🖨️ Salvar como PDF</button>
    <button class="btn-secundario" onclick="compartilharImagem()">🖼️ Compartilhar como Imagem</button>
  </div>
  <div class="status" id="statusImagem"></div>
  <div class="cabecalho">
    <div class="selo">田</div>
    <div><div class="titulo">TANÊSHIRO PRODUÇÃO</div><div class="sub">SISTEMA INTELIGENTE DE GESTÃO DA PRODUÇÃO</div></div>
  </div>
  <h1>${tituloTipo}</h1>
  <div class="periodo">${periodoTexto} — Lote(s): ${lotesRelatorio.length > 0 ? lotesRelatorio.map((l) => l.numero).join(", ") : "nenhum"}</div>

  <div class="bloco"><div class="rotulo">PLANEJADO × PRODUZIDO</div><div>Planejado (Recheio): <strong>${planejadoRecheioKg.toFixed(1)}kg</strong> · Produzido (Recheio): <strong>${produzidoRecheioKg.toFixed(1)}kg</strong></div><div>Produzido Total: <strong>${produzidoTotalKg.toFixed(1)}kg</strong></div></div>

  <div class="bloco"><div class="rotulo">PRODUÇÃO E RENDIMENTO</div>
    <div>Esperado: <strong>${totalEsperado}</strong> un. · Embalado: <strong>${totalEmbalado}</strong> un.</div>
    <div>${rendimento.emoji} ${rendimento.label} ${rendimento.pct != null ? `(${rendimento.pct.toFixed(1)}%)` : ""}</div>
  </div>

  ${turnoHtml}

  <div class="bloco"><div class="rotulo">PRODUÇÃO POR PRODUTO</div>
    <table><thead><tr><th>Produto</th><th style="text-align:right">Embalado</th><th style="text-align:right">Esperado</th><th style="text-align:right">Perda</th></tr></thead>
    <tbody>${linhasProduto || '<tr><td colspan="4">Sem dados</td></tr>'}</tbody></table>
  </div>

  <div class="bloco"><div class="rotulo">PERDAS POR SETOR</div>
    <div>Recheio: ${perdaRecheioKg.toFixed(1)}kg · Massa: ${perdaMassaKg.toFixed(1)}kg · Modelagem: ${perdaModelagemKg.toFixed(1)}kg</div>
    <div>Embalagem: ${perdaEmbalagemKg.toFixed(1)}kg ${perdaSobrasKg > 0 ? `· Sobras descartadas: ${perdaSobrasKg.toFixed(1)}kg` : ""}</div>
  </div>

  <div class="bloco" style="border-top:1px solid #E8E4DF; padding-top:10px; color:#8A837C; font-size:11px;">
    Responsável(is) pelo fechamento: ${responsaveis.length > 0 ? responsaveis.join(", ") : "nenhum lote fechado neste período"}<br/>
    Gerado por ${user.nome} em ${new Date().toLocaleString("pt-BR")}
  </div>

  <div id="canvasWrap" style="margin-top:20px;">
    <canvas id="canvasRelatorio" style="width:100%; max-width:640px; border:1px solid #E8E4DF; border-radius:8px;"></canvas>
  </div>

  <script>
    const DADOS = ${dadosImagemJson};

    function desenharImagem() {
      const canvas = document.getElementById('canvasRelatorio');
      const ctx = canvas.getContext('2d');
      const W = 800;
      const H = 420 + DADOS.produtos.length * 26;
      canvas.width = W; canvas.height = H;

      ctx.fillStyle = '#F5F3F0'; ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#C8161D'; ctx.fillRect(0, 0, W, 90);
      ctx.fillStyle = '#FFFFFF'; ctx.font = 'bold 24px Arial'; ctx.fillText('TANÊSHIRO PRODUÇÃO', 24, 42);
      ctx.font = '12px Arial'; ctx.fillText('SISTEMA INTELIGENTE DE GESTÃO DA PRODUÇÃO', 24, 64);

      let y = 130;
      ctx.fillStyle = '#161311'; ctx.font = 'bold 22px Arial'; ctx.fillText(DADOS.titulo, 24, y); y += 26;
      ctx.fillStyle = '#8A837C'; ctx.font = '14px Arial'; ctx.fillText(DADOS.periodo + ' — Lote(s): ' + DADOS.lotes, 24, y); y += 36;

      ctx.fillStyle = '#161311'; ctx.font = '15px Arial';
      ctx.fillText('Esperado: ' + DADOS.esperado + ' un.   Embalado: ' + DADOS.embalado + ' un.', 24, y); y += 24;
      ctx.fillText(DADOS.rendimentoTexto, 24, y); y += 24;
      ctx.fillStyle = '#8A837C'; ctx.font = '13px Arial'; ctx.fillText('Perdas: ' + DADOS.perdasTexto, 24, y, W - 48); y += 36;

      ctx.strokeStyle = '#E8E4DF'; ctx.beginPath(); ctx.moveTo(24, y); ctx.lineTo(W - 24, y); ctx.stroke(); y += 22;
      ctx.fillStyle = '#8A837C'; ctx.font = 'bold 13px Arial';
      ctx.fillText('PRODUTO', 24, y); ctx.fillText('EMB.', 520, y); ctx.fillText('ESP.', 600, y); ctx.fillText('PERDA', 680, y);
      y += 18;
      ctx.strokeStyle = '#E8E4DF'; ctx.beginPath(); ctx.moveTo(24, y); ctx.lineTo(W - 24, y); ctx.stroke(); y += 22;

      ctx.font = '14px Arial';
      DADOS.produtos.forEach((p) => {
        ctx.fillStyle = '#161311';
        ctx.fillText(p.nome, 24, y);
        ctx.fillText(String(p.embalado), 520, y);
        ctx.fillText(String(p.esperado), 600, y);
        ctx.fillText(p.perda + 'kg', 680, y);
        y += 26;
      });

      y += 14;
      ctx.strokeStyle = '#E8E4DF'; ctx.beginPath(); ctx.moveTo(24, y); ctx.lineTo(W - 24, y); ctx.stroke(); y += 20;
      ctx.fillStyle = '#8A837C'; ctx.font = '11px Arial'; ctx.fillText(DADOS.geradoPor, 24, y);
    }
    desenharImagem();

    function compartilharImagem() {
      const status = document.getElementById('statusImagem');
      const canvas = document.getElementById('canvasRelatorio');
      canvas.toBlob(async function (blob) {
        if (!blob) { status.textContent = 'Não foi possível gerar a imagem.'; return; }
        const nomeArquivo = 'relatorio-taneshiro.png';
        const file = new File([blob], nomeArquivo, { type: 'image/png' });
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          try {
            await navigator.share({ files: [file], title: DADOS.titulo, text: DADOS.titulo + ' — TANÊSHIRO PRODUÇÃO' });
            status.textContent = '';
          } catch (e) {
            status.textContent = '';
          }
        } else {
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url; a.download = nomeArquivo;
          document.body.appendChild(a); a.click(); document.body.removeChild(a);
          URL.revokeObjectURL(url);
          status.textContent = 'Compartilhamento direto não é suportado aqui — a imagem foi baixada. Anexe ela manualmente no WhatsApp.';
        }
      }, 'image/png');
    }
  </script>
</body></html>`;
  }

  function abrirRelatorioEmNovaAba() {
    const html = gerarHtmlRelatorio();
    const blob = new Blob([html], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const nova = window.open(url, "_blank");
    if (!nova) {
      setMensagem("O navegador bloqueou a abertura da nova aba. Permita pop-ups para este site e tente de novo.");
      setTimeout(() => setMensagem(""), 5000);
    }
  }

  function baixarCSV() {
    const linhas = [["Produto", "Esperado (un)", "Embalado (un)", "Perda (kg)"]];
    porProduto.forEach((x) => linhas.push([x.produto.nome, x.esperado, x.embalado, x.perdaKg.toFixed(1)]));
    const csv = linhas.map((l) => l.join(";")).join("\n");
    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `relatorio_${tipo}_${dataRef}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  return (
    <div className="space-y-4">
      <style>{`
        @media print {
          body * { visibility: hidden; }
          #relatorio-imprimivel, #relatorio-imprimivel * { visibility: visible; }
          #relatorio-imprimivel { position: absolute; left: 0; top: 0; width: 100%; }
        }
      `}</style>

      <div className="flex gap-2">
        {[
          { id: "diario", label: "Diário" },
          { id: "semanal", label: "Semanal" },
          { id: "mensal", label: "Mensal" },
        ].map((t) => (
          <button
            key={t.id}
            onClick={() => setTipo(t.id)}
            className="flex-1 rounded-lg py-2 text-xs font-semibold"
            style={{ background: tipo === t.id ? C.red : C.white, color: tipo === t.id ? C.white : C.gray900 }}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div className="rounded-2xl p-3" style={{ background: C.white }}>
        <input
          type={tipo === "mensal" ? "month" : "date"}
          value={tipo === "mensal" ? dataRef.slice(0, 7) : dataRef}
          onChange={(e) => setDataRef(tipo === "mensal" ? e.target.value + "-01" : e.target.value)}
          className="w-full rounded-lg px-3 py-2 text-sm outline-none"
          style={{ background: C.gray100, color: C.black }}
        />
      </div>

      {carregando ? (
        <div className="rounded-2xl p-8 text-center" style={{ background: C.white }}>
          <Loader2 size={20} className="animate-spin mx-auto mb-2" color={C.gray500} />
          <div className="text-xs" style={{ color: C.gray500 }}>Carregando dados...</div>
        </div>
      ) : (
        <>
          <div className="rounded-2xl p-4" style={{ background: C.white }}>
            <div className="text-xs font-semibold mb-3" style={{ color: C.gray500 }}>RESUMO DO PERÍODO</div>
            <div className="grid grid-cols-2 gap-3 mb-3">
              <div className="rounded-xl p-3" style={{ background: C.gray100 }}>
                <Soup size={14} color={C.red} />
                <div className="text-[10px] font-semibold mt-1" style={{ color: C.gray500 }}>Produzido (Total)</div>
                <div className="text-base font-bold" style={{ color: C.black }}>{produzidoTotalKg.toFixed(1)}<span className="text-[10px] font-normal"> kg</span></div>
              </div>
              <div className="rounded-xl p-3" style={{ background: C.gray100 }}>
                <Package size={14} color={C.red} />
                <div className="text-[10px] font-semibold mt-1" style={{ color: C.gray500 }}>Embalado</div>
                <div className="text-base font-bold" style={{ color: C.black }}>{totalEmbalado.toLocaleString("pt-BR")}<span className="text-[10px] font-normal"> un</span></div>
              </div>
              <div className="rounded-xl p-3" style={{ background: C.gray100 }}>
                <AlertTriangle size={14} color="#CA8A04" />
                <div className="text-[10px] font-semibold mt-1" style={{ color: C.gray500 }}>Perdas</div>
                <div className="text-base font-bold" style={{ color: C.black }}>{(perdaRecheioKg + perdaMassaKg + perdaModelagemKg + perdaEmbalagemKg).toFixed(1)}<span className="text-[10px] font-normal"> kg</span></div>
              </div>
              <div className="rounded-xl p-3" style={{ background: C.gray100 }}>
                <TrendingUp size={14} color="#16A34A" />
                <div className="text-[10px] font-semibold mt-1" style={{ color: C.gray500 }}>Rendimento</div>
                <div className="text-base font-bold" style={{ color: rendimento.color }}>{rendimento.pct != null ? `${rendimento.pct.toFixed(0)}%` : "-"}</div>
              </div>
            </div>

            {totalEsperado > 0 && (
              <div className="flex items-center gap-4 pt-3" style={{ borderTop: `1px solid ${C.gray200}` }}>
                <div
                  className="w-16 h-16 rounded-full flex items-center justify-center shrink-0"
                  style={{ background: `conic-gradient(${C.red} 0deg ${Math.min(360, (totalEmbalado / totalEsperado) * 360)}deg, ${C.gray200} ${Math.min(360, (totalEmbalado / totalEsperado) * 360)}deg 360deg)` }}
                >
                  <div className="w-11 h-11 rounded-full flex flex-col items-center justify-center" style={{ background: C.white }}>
                    <span className="text-[11px] font-bold" style={{ color: C.black }}>{rendimento.pct != null ? `${rendimento.pct.toFixed(0)}%` : "-"}</span>
                  </div>
                </div>
                <div className="text-xs" style={{ color: C.gray500 }}>
                  <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full inline-block" style={{ background: C.red }} /> Produção ({totalEmbalado} un.)</div>
                  <div className="flex items-center gap-1.5 mt-1"><span className="w-2.5 h-2.5 rounded-full inline-block" style={{ background: C.gray200 }} /> Diferença ({Math.max(0, totalEsperado - totalEmbalado)} un.)</div>
                </div>
              </div>
            )}
          </div>

          <div id="relatorio-imprimivel" className="rounded-2xl p-5" style={{ background: C.white }}>
            <div className="flex items-center gap-2 mb-1">
              <Seal size={28} />
              <div>
                <div className="font-bold text-sm" style={{ color: C.black }}>TANÊSHIRO PRODUÇÃO</div>
                <div className="text-[10px]" style={{ color: C.gray500 }}>Sistema Inteligente de Gestão da Produção</div>
              </div>
            </div>

            <div className="mt-3 pt-3" style={{ borderTop: `1px solid ${C.gray200}` }}>
              <div className="font-bold text-base" style={{ color: C.black }}>{tituloTipo}</div>
              <div className="text-xs" style={{ color: C.gray500 }}>{periodoTexto}</div>
              <div className="text-xs" style={{ color: C.gray500 }}>
                Lote(s): {lotesRelatorio.length > 0 ? lotesRelatorio.map((l) => l.numero).join(", ") : "nenhum"}
              </div>
            </div>

            {lotesRelatorio.length === 0 ? (
              <div className="text-sm mt-4" style={{ color: C.gray500 }}>Nenhum dado de produção neste período.</div>
            ) : (
              <>
                <div className="mt-4">
                  <div className="text-xs font-semibold mb-1" style={{ color: C.gray500 }}>PLANEJADO × PRODUZIDO</div>
                  <div className="text-sm" style={{ color: C.gray900 }}>Planejado (Recheio): <strong>{planejadoRecheioKg.toFixed(1)}kg</strong> · Produzido (Recheio): <strong>{produzidoRecheioKg.toFixed(1)}kg</strong></div>
                  <div className="text-sm mt-0.5" style={{ color: C.gray900 }}>Produzido Total: <strong>{produzidoTotalKg.toFixed(1)}kg</strong></div>
                </div>

                <div className="mt-4">
                  <div className="text-xs font-semibold mb-1" style={{ color: C.gray500 }}>PRODUÇÃO E RENDIMENTO</div>
                  <div className="text-sm" style={{ color: C.gray900 }}>
                    Esperado: <strong>{totalEsperado.toLocaleString("pt-BR")}</strong> un. · Embalado: <strong>{totalEmbalado.toLocaleString("pt-BR")}</strong> un.
                  </div>
                  <div className="text-sm flex items-center gap-1" style={{ color: rendimento.color }}>
                    {rendimento.emoji} {rendimento.label} {rendimento.pct != null && `(${rendimento.pct.toFixed(1)}%)`}
                  </div>
                </div>

                {tipo === "diario" && (
                  <div className="mt-4">
                    <div className="text-xs font-semibold mb-1" style={{ color: C.gray500 }}>PRODUÇÃO POR TURNO</div>
                    <div className="text-sm" style={{ color: C.gray900 }}>☀️ Matutino: <strong>{embMatutino}</strong> un. · 🌙 Vespertino: <strong>{embVespertino}</strong> un.</div>
                  </div>
                )}

                <div className="mt-4">
                  <div className="text-xs font-semibold mb-1" style={{ color: C.gray500 }}>PRODUÇÃO POR PRODUTO</div>
                  <div className="space-y-1">
                    {porProduto.map((x) => (
                      <div key={x.produto.id} className="flex items-center justify-between text-xs">
                        <span style={{ color: C.gray900 }}>{x.produto.nome}</span>
                        <span style={{ color: C.gray500 }}>{x.embalado}/{x.esperado} un.{x.perdaKg > 0 && ` · ${x.perdaKg.toFixed(1)}kg perda`}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="mt-4">
                  <div className="text-xs font-semibold mb-1" style={{ color: C.gray500 }}>PERDAS POR SETOR</div>
                  <div className="text-xs space-y-0.5" style={{ color: C.gray900 }}>
                    <div>Recheio: {perdaRecheioKg.toFixed(1)}kg · Massa: {perdaMassaKg.toFixed(1)}kg · Modelagem: {perdaModelagemKg.toFixed(1)}kg</div>
                    <div>Embalagem: {perdaEmbalagemKg.toFixed(1)}kg {perdaSobrasKg > 0 && `· Sobras descartadas: ${perdaSobrasKg.toFixed(1)}kg`}</div>
                  </div>
                </div>

                <div className="mt-4 pt-3" style={{ borderTop: `1px solid ${C.gray200}` }}>
                  <div className="text-xs" style={{ color: C.gray500 }}>
                    Responsável(is) pelo fechamento: {responsaveis.length > 0 ? responsaveis.join(", ") : "nenhum lote fechado neste período"}
                  </div>
                  <div className="text-[10px] mt-1" style={{ color: C.gray500 }}>Gerado por {user.nome} em {new Date().toLocaleString("pt-BR")}</div>
                </div>
              </>
            )}
          </div>

          <div className="grid grid-cols-2 gap-2">
            <button onClick={abrirRelatorioEmNovaAba} className="flex flex-col items-center gap-1 rounded-xl py-3" style={{ background: C.white }}>
              <Share2 size={16} color={C.red} />
              <span className="text-[10px] font-semibold" style={{ color: C.black }}>PDF / Imagem</span>
            </button>
            <button onClick={baixarCSV} className="flex flex-col items-center gap-1 rounded-xl py-3" style={{ background: C.white }}>
              <Download size={16} color={C.red} />
              <span className="text-[10px] font-semibold" style={{ color: C.black }}>Exportar CSV</span>
            </button>
          </div>
          <div className="text-[11px] text-center" style={{ color: C.gray500 }}>
            "PDF / Imagem" abre o relatório numa aba nova, com opção de salvar como PDF ou compartilhar como imagem direto no WhatsApp.
          </div>
          {mensagem && (
            <div className="rounded-xl p-3 text-xs text-center" style={{ background: C.redSoft, color: C.redDark }}>{mensagem}</div>
          )}

          <button
            onClick={() => setMostrarLancamentos((v) => !v)}
            className="w-full flex items-center justify-center gap-1.5 rounded-xl py-3 text-xs font-semibold"
            style={{ background: C.white, color: C.black }}
          >
            <Pencil size={13} color={C.red} />
            {mostrarLancamentos ? "Ocultar lançamentos do período" : "Corrigir um lançamento deste período"}
          </button>

          {mostrarLancamentos && (
            <div className="space-y-2">
              <div className="text-xs" style={{ color: C.gray500 }}>
                {lancamentosEditaveis.length} lançamento(s) neste período. Toque em "Editar" para corrigir peso, quantidade ou observações.
              </div>
              {lancamentosEditaveis.length === 0 && (
                <div className="rounded-2xl p-6 text-center" style={{ background: C.white }}>
                  <div className="text-sm" style={{ color: C.gray500 }}>Nenhum lançamento neste período.</div>
                </div>
              )}
              {lancamentosEditaveis.map((item, i) => (
                <div key={item.tipo + (item.registro.id || i)} className="rounded-xl p-3" style={{ background: C.white }}>
                  <div className="flex items-center justify-between text-sm">
                    <span className="font-medium" style={{ color: C.black }}>{nomeProduto(item.registro.produtoId)}</span>
                    <span style={{ color: C.gray500 }}>{resumoLancamento(item)}</span>
                  </div>
                  <div className="flex items-center justify-between text-[11px] mt-1" style={{ color: C.gray500 }}>
                    <span>
                      {TIPO_LABEL_LANCAMENTO[item.tipo]}
                      {item.registro.turno ? ` · ${item.registro.turno === "matutino" ? "☀️" : "🌙"}` : ""}
                      {item.loteNumero ? ` · Lote ${item.loteNumero}` : ""}
                    </span>
                    <span>{item.registro.horario ? new Date(item.registro.horario).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }) : ""}</span>
                  </div>
                  <div className="flex items-center justify-between mt-1.5">
                    <span className="text-[11px] font-semibold" style={{ color: C.gray900 }}>{item.registro.usuario}</span>
                    {podeEditar(item) ? (
                      <button
                        onClick={() => setEditando(item)}
                        className="flex items-center gap-1 text-[11px] font-semibold rounded-lg px-2 py-1"
                        style={{ background: C.redSoft, color: C.redDark }}
                      >
                        ✏️ Editar
                      </button>
                    ) : (
                      <span className="text-[11px]" style={{ color: C.gray500 }}>Somente o autor ou um administrador pode editar</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </>
      )}

      {editando && (
        <EditarRegistroModal
          titulo={`${TIPO_LABEL_LANCAMENTO[editando.tipo]} — ${nomeProduto(editando.registro.produtoId)}`}
          subtitulo={editando.loteNumero ? `Lote ${editando.loteNumero} · ${fmtData(editando.loteData)}` : fmtData((editando.registro.registradoEm || "").slice(0, 10))}
          campos={camposEditaveisPara(editando)}
          valores={editando.registro}
          onSalvar={salvarEdicao}
          onFechar={() => setEditando(null)}
        />
      )}
    </div>
  );
}

function UsuariosScreen({ currentUser, users, requests, onSalvar, onCriar, onResetSenha, onAlternarStatus, onExcluir, onAprovar, onBack }) {
  const [editando, setEditando] = useState(null); // null | id do usuário | "novo"

  if (editando !== null) {
    const usuarioAtual = editando === "novo" ? null : users.find((u) => u.id === editando);
    return (
      <UsuarioForm
        usuario={usuarioAtual}
        souEu={usuarioAtual?.id === currentUser.id}
        onSalvarEdicao={async (dados) => {
          await onSalvar(dados, usuarioAtual.id);
          setEditando(null);
        }}
        onCriar={async (dados) => {
          const r = await onCriar(dados);
          if (r.ok) setEditando(null);
          return r;
        }}
        onResetSenha={onResetSenha}
        onAlternarStatus={async (id) => {
          await onAlternarStatus(id);
          setEditando(null);
        }}
        onExcluir={async (id) => {
          await onExcluir(id);
          setEditando(null);
        }}
        onCancelar={() => setEditando(null)}
      />
    );
  }

  const ordenados = [...users].sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onBack} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="font-bold text-lg mb-1" style={{ color: C.black }}>Usuários</div>
      <div className="text-sm mb-4" style={{ color: C.gray500 }}>Gerencie perfis, senhas e acessos da equipe.</div>

      {requests.length > 0 && (
        <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
          <div className="font-semibold text-sm mb-3" style={{ color: C.black }}>Solicitações de cadastro ({requests.length})</div>
          <div className="space-y-2">
            {requests.map((r) => (
              <div key={r.id} className="flex items-center justify-between rounded-xl px-3 py-2.5" style={{ background: C.gray100 }}>
                <div>
                  <div className="text-sm font-medium" style={{ color: C.black }}>{r.nome}</div>
                  <div className="text-xs" style={{ color: C.gray500 }}>@{r.usuario}</div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => onAprovar(r.id, true)} className="w-8 h-8 rounded-lg flex items-center justify-center text-white" style={{ background: C.red }}>
                    <Check size={15} />
                  </button>
                  <button onClick={() => onAprovar(r.id, false)} className="w-8 h-8 rounded-lg flex items-center justify-center" style={{ background: C.gray200, color: C.gray900 }}>
                    <X size={15} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <button
        onClick={() => setEditando("novo")}
        className="w-full flex items-center justify-center gap-2 rounded-xl py-3 font-semibold text-white text-sm mb-4"
        style={{ background: C.red }}
      >
        <Plus size={16} /> Criar Usuário
      </button>

      <div className="space-y-2">
        {ordenados.map((u) => {
          const perfilCor = PERFIL_COR[u.perfil] || { bg: C.gray100, cor: C.gray900 };
          const bloqueado = u.status !== "ativo";
          return (
            <button key={u.id} onClick={() => setEditando(u.id)} className="w-full flex items-center gap-3 rounded-2xl p-3 text-left" style={{ background: C.white }}>
              <div className="w-10 h-10 rounded-full flex items-center justify-center text-white text-sm font-bold shrink-0" style={{ background: bloqueado ? C.gray500 : C.red }}>
                {u.nome.charAt(0)}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-medium truncate" style={{ color: C.black }}>{u.nome} {u.id === currentUser.id && <span style={{ color: C.gray500 }}>(você)</span>}</div>
                <div className="text-[11px]" style={{ color: C.gray500 }}>@{u.usuario}</div>
              </div>
              <div className="flex flex-col items-end gap-1 shrink-0">
                <span className="text-[10px] font-semibold px-2 py-1 rounded-full" style={{ background: perfilCor.bg, color: perfilCor.cor }}>
                  {u.perfil}
                </span>
                {bloqueado && (
                  <span className="text-[10px] font-semibold px-2 py-1 rounded-full" style={{ background: C.gray100, color: C.gray500 }}>
                    Bloqueado
                  </span>
                )}
              </div>
            </button>
          );
        })}
      </div>
    </main>
  );
}

function UsuarioForm({ usuario, souEu, onSalvarEdicao, onCriar, onResetSenha, onAlternarStatus, onExcluir, onCancelar }) {
  const novo = !usuario;
  const [nome, setNome] = useState(usuario?.nome || "");
  const [perfil, setPerfil] = useState(usuario?.perfil || "Produção");
  const [usuarioLogin, setUsuarioLogin] = useState("");
  const [senha, setSenha] = useState("");
  const [confirmar, setConfirmar] = useState("");
  const [erro, setErro] = useState("");
  const [salvando, setSalvando] = useState(false);
  const lockRef = useRef(false);

  const [novaSenha, setNovaSenha] = useState("");
  const [novaSenhaConfirmar, setNovaSenhaConfirmar] = useState("");
  const [erroSenha, setErroSenha] = useState("");
  const [redefinindo, setRedefinindo] = useState(false);
  const senhaLockRef = useRef(false);

  const [confirmandoExclusao, setConfirmandoExclusao] = useState(false);
  const [excluindo, setExcluindo] = useState(false);

  async function salvar() {
    if (lockRef.current) return;
    if (novo) {
      if (!nome.trim() || !usuarioLogin.trim() || !senha) return setErro("Preencha todos os campos.");
      if (senha !== confirmar) return setErro("As senhas não coincidem.");
      lockRef.current = true;
      setErro("");
      setSalvando(true);
      try {
        const r = await onCriar({ nome: nome.trim(), usuario: usuarioLogin.trim(), senha, perfil });
        if (!r.ok) setErro(r.msg);
      } finally {
        lockRef.current = false;
        setSalvando(false);
      }
    } else {
      if (!nome.trim()) return setErro("Dê um nome ao usuário.");
      lockRef.current = true;
      setErro("");
      setSalvando(true);
      try {
        await onSalvarEdicao({ nome: nome.trim(), perfil });
      } finally {
        lockRef.current = false;
        setSalvando(false);
      }
    }
  }

  async function confirmarNovaSenha() {
    if (senhaLockRef.current) return;
    if (!novaSenha || novaSenha.length < 4) return setErroSenha("A senha precisa ter pelo menos 4 caracteres.");
    if (novaSenha !== novaSenhaConfirmar) return setErroSenha("As senhas não coincidem.");
    senhaLockRef.current = true;
    setErroSenha("");
    setRedefinindo(true);
    try {
      await onResetSenha(usuario.id, novaSenha);
      setNovaSenha("");
      setNovaSenhaConfirmar("");
    } finally {
      senhaLockRef.current = false;
      setRedefinindo(false);
    }
  }

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onCancelar} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="font-bold text-lg mb-4" style={{ color: C.black }}>
        {novo ? "Criar Usuário" : `Editar — ${usuario.nome}`}
      </div>

      <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
        <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Nome completo</label>
        <input type="text" value={nome} onChange={(e) => setNome(e.target.value)}
          className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1 mb-3" style={{ background: C.gray100, color: C.black }} />

        {novo ? (
          <>
            <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Usuário (login)</label>
            <input type="text" autoCapitalize="none" autoCorrect="off" value={usuarioLogin} onChange={(e) => setUsuarioLogin(e.target.value)}
              className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1 mb-3" style={{ background: C.gray100, color: C.black }} />
            <div className="grid grid-cols-2 gap-3 mb-3">
              <div>
                <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Senha</label>
                <input type="password" value={senha} onChange={(e) => setSenha(e.target.value)}
                  className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }} />
              </div>
              <div>
                <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Confirmar</label>
                <input type="password" value={confirmar} onChange={(e) => setConfirmar(e.target.value)}
                  className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }} />
              </div>
            </div>
          </>
        ) : (
          <div className="text-xs mb-3" style={{ color: C.gray500 }}>Usuário: <strong style={{ color: C.gray900 }}>@{usuario.usuario}</strong></div>
        )}

        <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Perfil</label>
        <select value={perfil} onChange={(e) => setPerfil(e.target.value)}
          className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }}>
          <option value="Produção">Produção</option>
          <option value="Supervisor">Supervisor</option>
          <option value="Administrador">Administrador</option>
        </select>

        {erro && <div className="rounded-xl p-3 mt-3 text-sm" style={{ background: C.redSoft, color: C.redDark }}>{erro}</div>}

        <button onClick={salvar} disabled={salvando} className="w-full flex items-center justify-center gap-2 rounded-xl py-3 font-semibold text-white text-sm mt-3" style={{ background: C.red, opacity: salvando ? 0.6 : 1 }}>
          <Save size={16} /> {salvando ? "Salvando..." : novo ? "Criar usuário" : "Salvar alterações"}
        </button>
      </div>

      {!novo && (
        <>
          <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
            <div className="font-semibold text-sm mb-2" style={{ color: C.black }}>Redefinir senha</div>
            <div className="grid grid-cols-2 gap-3 mb-2">
              <input type="password" placeholder="Nova senha" value={novaSenha} onChange={(e) => setNovaSenha(e.target.value)}
                className="w-full rounded-lg px-3 py-2 text-sm outline-none" style={{ background: C.gray100, color: C.black }} />
              <input type="password" placeholder="Confirmar" value={novaSenhaConfirmar} onChange={(e) => setNovaSenhaConfirmar(e.target.value)}
                className="w-full rounded-lg px-3 py-2 text-sm outline-none" style={{ background: C.gray100, color: C.black }} />
            </div>
            {erroSenha && <div className="rounded-xl p-2.5 mb-2 text-xs" style={{ background: C.redSoft, color: C.redDark }}>{erroSenha}</div>}
            <button onClick={confirmarNovaSenha} disabled={redefinindo} className="w-full rounded-xl py-2.5 text-sm font-semibold" style={{ background: C.gray100, color: C.gray900, opacity: redefinindo ? 0.6 : 1 }}>
              {redefinindo ? "Redefinindo..." : "Redefinir senha"}
            </button>
          </div>

          {!souEu && (
            <div className="rounded-2xl p-4" style={{ background: C.white }}>
              <div className="font-semibold text-sm mb-3" style={{ color: C.black }}>Acesso</div>
              <button onClick={() => onAlternarStatus(usuario.id)} className="w-full rounded-xl py-2.5 text-sm font-semibold mb-2" style={{ background: usuario.status === "ativo" ? "#FEF3C7" : "#ECFDF5", color: usuario.status === "ativo" ? "#92400E" : "#059669" }}>
                {usuario.status === "ativo" ? "🚫 Bloquear usuário" : "🔓 Reativar usuário"}
              </button>

              {!confirmandoExclusao ? (
                <button onClick={() => setConfirmandoExclusao(true)} className="w-full rounded-xl py-2.5 text-sm font-semibold" style={{ background: C.redSoft, color: C.redDark }}>
                  🗑️ Excluir usuário
                </button>
              ) : (
                <div className="rounded-xl p-3" style={{ background: C.redSoft }}>
                  <div className="text-xs font-semibold mb-2" style={{ color: C.redDark }}>Tem certeza? Essa ação não pode ser desfeita.</div>
                  <div className="flex gap-2">
                    <button onClick={() => setConfirmandoExclusao(false)} className="flex-1 rounded-lg py-2 text-xs font-semibold" style={{ background: C.white, color: C.gray900 }}>Cancelar</button>
                    <button
                      onClick={async () => {
                        setExcluindo(true);
                        try {
                          await onExcluir(usuario.id);
                        } finally {
                          setExcluindo(false);
                        }
                      }}
                      disabled={excluindo}
                      className="flex-1 rounded-lg py-2 text-xs font-semibold text-white"
                      style={{ background: C.redDark, opacity: excluindo ? 0.6 : 1 }}
                    >
                      {excluindo ? "Excluindo..." : "Sim, excluir"}
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}
        </>
      )}
    </main>
  );
}

function ProdutosScreen({ produtos, onSalvar, onBack }) {
  const [busca, setBusca] = useState("");
  const [editando, setEditando] = useState(null); // null | id do produto | "novo"

  const filtrados = [...produtos]
    .filter((p) => p.nome.toLowerCase().includes(busca.toLowerCase()))
    .sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));

  if (editando !== null) {
    const produtoAtual = editando === "novo" ? null : produtos.find((p) => p.id === editando);
    return (
      <ProdutoForm
        produto={produtoAtual}
        onSalvar={async (dados) => {
          await onSalvar(dados, produtoAtual?.id);
          setEditando(null);
        }}
        onCancelar={() => setEditando(null)}
      />
    );
  }

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onBack} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="flex items-center justify-between mb-1">
        <div className="font-bold text-lg" style={{ color: C.black }}>Produtos</div>
      </div>
      <div className="text-sm mb-4" style={{ color: C.gray500 }}>Ficha técnica de cada salgado — pesos, catupiry, empanamento e validade.</div>

      <button
        onClick={() => setEditando("novo")}
        className="w-full flex items-center justify-center gap-2 rounded-xl py-3 font-semibold text-white text-sm mb-4"
        style={{ background: C.red }}
      >
        <Plus size={16} /> Novo Produto
      </button>

      <input
        type="text"
        placeholder="Buscar produto..."
        value={busca}
        onChange={(e) => setBusca(e.target.value)}
        className="w-full rounded-xl px-3 py-2.5 text-sm outline-none mb-3"
        style={{ background: C.white, color: C.black }}
      />

      <div className="space-y-2">
        {filtrados.length === 0 && (
          <div className="rounded-2xl p-6 text-center" style={{ background: C.white }}>
            <div className="text-sm" style={{ color: C.gray500 }}>Nenhum produto encontrado.</div>
          </div>
        )}
        {filtrados.map((p) => (
          <button key={p.id} onClick={() => setEditando(p.id)} className="w-full flex items-center gap-3 rounded-2xl p-3 text-left" style={{ background: C.white }}>
            <div className="w-10 h-10 rounded-full flex items-center justify-center text-lg shrink-0" style={{ background: C.gray100 }}>
              {iconeProduto(p.nome)}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium truncate" style={{ color: C.black }}>{p.nome}</div>
              <div className="text-[11px]" style={{ color: C.gray500 }}>
                {p.pesoMassa > 0 && `massa ${p.pesoMassa}g `}
                {p.pesoRecheio > 0 && `· recheio ${p.pesoRecheio}g `}
                {p.temCatupiry && "· catupiry "}
                {p.empana && "· empanado"}
              </div>
            </div>
            <span
              className="text-[10px] font-semibold px-2 py-1 rounded-full shrink-0"
              style={{ background: p.status === "ativo" ? "#ECFDF5" : C.gray100, color: p.status === "ativo" ? "#059669" : C.gray500 }}
            >
              {p.status === "ativo" ? "Ativo" : "Inativo"}
            </span>
          </button>
        ))}
      </div>
    </main>
  );
}

function ProdutoForm({ produto, onSalvar, onCancelar }) {
  const [nome, setNome] = useState(produto?.nome || "");
  const [pesoMassa, setPesoMassa] = useState(String(produto?.pesoMassa ?? 12));
  const [pesoRecheio, setPesoRecheio] = useState(String(produto?.pesoRecheio ?? 4));
  const [temCatupiry, setTemCatupiry] = useState(!!produto?.temCatupiry);
  const [pesoCatupiry, setPesoCatupiry] = useState(String(produto?.pesoCatupiry ?? 0));
  const [empana, setEmpana] = useState(produto ? !!produto.empana : true);
  const [validadeDias, setValidadeDias] = useState(String(produto?.validadeDias ?? 90));
  const [status, setStatus] = useState(produto?.status || "ativo");
  const [erro, setErro] = useState("");
  const [salvando, setSalvando] = useState(false);
  const lockRef = useRef(false);

  async function confirmar() {
    if (!nome.trim()) return setErro("Dê um nome ao produto.");
    if (lockRef.current) return;
    lockRef.current = true;
    setErro("");
    setSalvando(true);
    try {
      await onSalvar({
        nome: nome.trim(),
        pesoMassa: parseFloat(pesoMassa) || 0,
        pesoRecheio: parseFloat(pesoRecheio) || 0,
        pesoCatupiry: temCatupiry ? parseFloat(pesoCatupiry) || 0 : 0,
        temCatupiry,
        empana,
        validadeDias: parseInt(validadeDias) || 90,
        status,
      });
    } finally {
      lockRef.current = false;
      setSalvando(false);
    }
  }

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onCancelar} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="font-bold text-lg mb-4" style={{ color: C.black }}>
        {produto ? `Editar — ${produto.nome}` : "Novo Produto"}
      </div>

      <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
        <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Nome do produto</label>
        <input
          type="text" value={nome} onChange={(e) => setNome(e.target.value)}
          placeholder="Ex: Coxinha com Catupiry"
          className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1 mb-3"
          style={{ background: C.gray100, color: C.black }}
        />

        <div className="grid grid-cols-2 gap-3 mb-3">
          <div>
            <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Peso da massa (g)</label>
            <input type="number" min="0" step="0.5" value={pesoMassa} onChange={(e) => setPesoMassa(e.target.value)}
              className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }} />
            <div className="text-[10px] mt-0.5" style={{ color: C.gray500 }}>0 se a massa for de fora (ex: pastéis)</div>
          </div>
          <div>
            <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Peso do recheio (g)</label>
            <input type="number" min="0" step="0.5" value={pesoRecheio} onChange={(e) => setPesoRecheio(e.target.value)}
              className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }} />
            <div className="text-[10px] mt-0.5" style={{ color: C.gray500 }}>0 se não tiver recheio (ex: kibes)</div>
          </div>
        </div>

        <label className="flex items-center gap-2 mb-2">
          <input type="checkbox" checked={temCatupiry} onChange={(e) => setTemCatupiry(e.target.checked)} />
          <span className="text-sm" style={{ color: C.gray900 }}>Usa catupiry</span>
        </label>
        {temCatupiry && (
          <div className="mb-3">
            <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Peso do catupiry (g)</label>
            <input type="number" min="0" step="0.5" value={pesoCatupiry} onChange={(e) => setPesoCatupiry(e.target.value)}
              className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }} />
            <div className="text-[10px] mt-0.5" style={{ color: C.gray500 }}>Deixe 0 se o catupiry já vier embutido no peso do recheio</div>
          </div>
        )}

        <label className="flex items-center gap-2 mb-3">
          <input type="checkbox" checked={empana} onChange={(e) => setEmpana(e.target.checked)} />
          <span className="text-sm" style={{ color: C.gray900 }}>Passa por empanamento</span>
        </label>

        <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Validade (dias)</label>
        <input type="number" min="1" step="1" value={validadeDias} onChange={(e) => setValidadeDias(e.target.value)}
          className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1 mb-3" style={{ background: C.gray100, color: C.black }} />

        <label className="text-xs font-semibold" style={{ color: C.gray500 }}>Status</label>
        <select value={status} onChange={(e) => setStatus(e.target.value)}
          className="w-full rounded-lg px-3 py-2 text-sm outline-none mt-1" style={{ background: C.gray100, color: C.black }}>
          <option value="ativo">Ativo</option>
          <option value="inativo">Inativo</option>
        </select>
        {status === "inativo" && (
          <div className="text-[11px] mt-1" style={{ color: C.gray500 }}>Produtos inativos somem das listas de lançamento, mas o histórico continua intacto.</div>
        )}
      </div>

      {erro && <div className="rounded-xl p-3 mb-3 text-sm" style={{ background: C.redSoft, color: C.redDark }}>{erro}</div>}

      <button
        onClick={confirmar}
        disabled={salvando}
        className="w-full flex items-center justify-center gap-2 rounded-xl py-3 font-semibold text-white text-sm"
        style={{ background: C.red, opacity: salvando ? 0.6 : 1 }}
      >
        <Save size={16} /> {salvando ? "Salvando..." : "Salvar"}
      </button>
    </main>
  );
}

function AuditoriaScreen({ produtos, users, logs, lote, historicoLotes, onCarregarHistorico, onBack }) {
  const [aba, setAba] = useState("lancamentos"); // lancamentos | acessos
  const [carregando, setCarregando] = useState(true);
  const [filtroUsuario, setFiltroUsuario] = useState("todos");
  const [filtroTipo, setFiltroTipo] = useState("todos");
  const [periodo, setPeriodo] = useState("semana"); // hoje | semana | mes | tudo

  useEffect(() => {
    (async () => {
      await onCarregarHistorico();
      setCarregando(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const nomeProduto = (id) => produtos.find((p) => p.id === id)?.nome || id;

  const hojeISO = localISO();
  const semanaAtual = segundaFeiraDe(hojeISO);
  const mesAtual = hojeISO.slice(0, 7);

  const todosLotes = [...historicoLotes.filter((l) => !(l.ano === lote.ano && l.numero === lote.numero)), lote];
  const lotesPeriodo = todosLotes.filter((l) => {
    if (periodo === "hoje") return l.data === hojeISO;
    if (periodo === "semana") return l.data >= semanaAtual && l.data <= hojeISO;
    if (periodo === "mes") return l.data.slice(0, 7) === mesAtual;
    return true;
  });

  // ---- Lançamentos (todos os registros de produção, de todas as etapas) ----
  const lancamentos = [];
  lotesPeriodo.forEach((l) => {
    l.recheios.forEach((r) => lancamentos.push({ tipo: "recheio", produtoId: r.produtoId, resumo: `${r.peso}kg`, usuario: r.usuario, turno: r.turno, data: l.data, loteNumero: l.numero, horario: r.horario }));
    l.massas.forEach((m) => lancamentos.push({ tipo: "massa", produtoId: m.produtoId, resumo: `${m.peso}kg`, usuario: m.usuario, turno: m.turno, data: l.data, loteNumero: l.numero, horario: m.horario }));
    l.modelagens.forEach((md) => {
      const partes = [];
      if (md.massaUtilizada != null) partes.push(`massa ${md.massaUtilizada}kg`);
      if (md.recheioUtilizado != null) partes.push(`recheio ${md.recheioUtilizado}kg`);
      lancamentos.push({ tipo: "modelagem", produtoId: md.produtoId, resumo: partes.join(" · ") || "-", usuario: md.usuario, turno: md.turno, data: l.data, loteNumero: l.numero, horario: md.horario });
    });
    l.embalagens.forEach((e) => lancamentos.push({ tipo: "embalagem", produtoId: e.produtoId, resumo: `${e.quantidadeEmbalada}un.`, usuario: e.usuario, turno: e.turno, data: l.data, loteNumero: l.numero, horario: e.horario }));
  });

  const lancamentosFiltrados = lancamentos
    .filter((e) => filtroUsuario === "todos" || e.usuario === filtroUsuario)
    .filter((e) => filtroTipo === "todos" || e.tipo === filtroTipo)
    .sort((a, b) => (a.horario < b.horario ? 1 : -1));

  // ---- Acessos e outras ações administrativas ----
  const acessosFiltrados = logs
    .filter((lg) => filtroUsuario === "todos" || lg.usuario === filtroUsuario)
    .filter((lg) => {
      if (periodo === "tudo") return true;
      const d = localISO(new Date(lg.horario));
      if (periodo === "hoje") return d === hojeISO;
      if (periodo === "semana") return d >= semanaAtual && d <= hojeISO;
      return d.slice(0, 7) === mesAtual;
    })
    .sort((a, b) => (a.horario < b.horario ? 1 : -1));

  const nomesUsuarios = [...new Set([...users.map((u) => u.nome), ...logs.map((l) => l.usuario)])].sort();

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onBack} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="font-bold text-lg mb-1" style={{ color: C.black }}>Auditoria</div>
      <div className="text-sm mb-4" style={{ color: C.gray500 }}>Quem acessou o sistema e quem lançou cada registro.</div>

      <div className="flex gap-2 mb-3">
        <button onClick={() => setAba("lancamentos")} className="flex-1 rounded-lg py-2 text-xs font-semibold" style={{ background: aba === "lancamentos" ? C.red : C.white, color: aba === "lancamentos" ? C.white : C.gray900 }}>
          Lançamentos
        </button>
        <button onClick={() => setAba("acessos")} className="flex-1 rounded-lg py-2 text-xs font-semibold" style={{ background: aba === "acessos" ? C.red : C.white, color: aba === "acessos" ? C.white : C.gray900 }}>
          Acessos e ações
        </button>
      </div>

      <div className="flex gap-2 mb-3">
        {[
          { id: "hoje", label: "Hoje" },
          { id: "semana", label: "Semana" },
          { id: "mes", label: "Mês" },
          { id: "tudo", label: "Tudo" },
        ].map((p) => (
          <button key={p.id} onClick={() => setPeriodo(p.id)} className="flex-1 rounded-lg py-1.5 text-[11px] font-semibold" style={{ background: periodo === p.id ? C.gray900 : C.white, color: periodo === p.id ? C.white : C.gray900 }}>
            {p.label}
          </button>
        ))}
      </div>

      <div className={`grid ${aba === "lancamentos" ? "grid-cols-2" : "grid-cols-1"} gap-2 mb-4`}>
        <select value={filtroUsuario} onChange={(e) => setFiltroUsuario(e.target.value)} className="rounded-lg px-2 py-2 text-[11px] outline-none" style={{ background: C.white, color: C.black }}>
          <option value="todos">Todos os usuários</option>
          {nomesUsuarios.map((n) => (
            <option key={n} value={n}>{n}</option>
          ))}
        </select>
        {aba === "lancamentos" && (
          <select value={filtroTipo} onChange={(e) => setFiltroTipo(e.target.value)} className="rounded-lg px-2 py-2 text-[11px] outline-none" style={{ background: C.white, color: C.black }}>
            <option value="todos">Todas etapas</option>
            <option value="recheio">Recheio</option>
            <option value="massa">Massa</option>
            <option value="modelagem">Modelagem</option>
            <option value="embalagem">Embalagem</option>
          </select>
        )}
      </div>

      {carregando ? (
        <div className="rounded-2xl p-8 text-center" style={{ background: C.white }}>
          <Loader2 size={20} className="animate-spin mx-auto mb-2" color={C.gray500} />
          <div className="text-xs" style={{ color: C.gray500 }}>Carregando histórico...</div>
        </div>
      ) : aba === "lancamentos" ? (
        <div className="space-y-2">
          <div className="text-xs" style={{ color: C.gray500 }}>{lancamentosFiltrados.length} lançamento(s)</div>
          {lancamentosFiltrados.length === 0 && (
            <div className="rounded-2xl p-6 text-center" style={{ background: C.white }}>
              <div className="text-sm" style={{ color: C.gray500 }}>Nenhum lançamento encontrado com esses filtros.</div>
            </div>
          )}
          {lancamentosFiltrados.map((e, i) => (
            <div key={i} className="rounded-xl p-3" style={{ background: C.white }}>
              <div className="flex items-center justify-between text-sm">
                <span className="font-medium" style={{ color: C.black }}>{nomeProduto(e.produtoId)}</span>
                <span style={{ color: C.gray500 }}>{e.resumo}</span>
              </div>
              <div className="flex items-center justify-between text-[11px] mt-1" style={{ color: C.gray500 }}>
                <span>{ETAPA_PERDA_LABEL[e.tipo] || e.tipo} · {e.turno === "matutino" ? "☀️" : "🌙"} · Lote {e.loteNumero}</span>
                <span>{fmtData(e.data)}</span>
              </div>
              <div className="flex items-center justify-between text-[11px] mt-0.5" style={{ color: C.gray900 }}>
                <span className="font-semibold">{e.usuario}</span>
                <span style={{ color: C.gray500 }}>{new Date(e.horario).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="space-y-2">
          <div className="text-xs" style={{ color: C.gray500 }}>{acessosFiltrados.length} evento(s)</div>
          {acessosFiltrados.length === 0 && (
            <div className="rounded-2xl p-6 text-center" style={{ background: C.white }}>
              <div className="text-sm" style={{ color: C.gray500 }}>Nenhum acesso ou ação encontrado com esses filtros.</div>
            </div>
          )}
          {acessosFiltrados.map((lg) => (
            <div key={lg.id} className="rounded-xl p-3" style={{ background: C.white }}>
              <div className="flex items-center justify-between text-sm">
                <span className="font-medium flex items-center gap-1.5" style={{ color: C.black }}>
                  {LOG_TIPO_ICONE[lg.tipo] || "•"} {LOG_TIPO_LABEL[lg.tipo] || lg.tipo}
                </span>
                <span style={{ color: C.gray500 }}>{new Date(lg.horario).toLocaleDateString("pt-BR")} {new Date(lg.horario).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span>
              </div>
              <div className="text-[11px] mt-1 font-semibold" style={{ color: C.gray900 }}>{lg.usuario}</div>
              {lg.detalhe && <div className="text-[11px] mt-0.5" style={{ color: C.gray500 }}>{lg.detalhe}</div>}
            </div>
          ))}
        </div>
      )}
    </main>
  );
}

function PerdasScreen({ produtos, lote, historicoLotes, onCarregarHistorico, onBack }) {
  const [carregando, setCarregando] = useState(true);
  const [periodo, setPeriodo] = useState("semana"); // hoje | semana | mes | tudo
  const [filtroProduto, setFiltroProduto] = useState("todos");
  const [filtroEtapa, setFiltroEtapa] = useState("todas");
  const [filtroTurno, setFiltroTurno] = useState("todos");

  useEffect(() => {
    (async () => {
      await onCarregarHistorico();
      setCarregando(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const ativos = produtos.filter((p) => p.status === "ativo");
  const nomeProduto = (id) => produtos.find((p) => p.id === id)?.nome || id;

  const hojeISO = localISO();
  const semanaAtual = segundaFeiraDe(hojeISO);
  const mesAtual = hojeISO.slice(0, 7);

  const todosLotes = [...historicoLotes.filter((l) => !(l.ano === lote.ano && l.numero === lote.numero)), lote];

  const lotesPeriodo = todosLotes.filter((l) => {
    if (periodo === "hoje") return l.data === hojeISO;
    if (periodo === "semana") return l.data >= semanaAtual && l.data <= hojeISO;
    if (periodo === "mes") return l.data.slice(0, 7) === mesAtual;
    return true; // tudo
  });

  const eventos = [];
  lotesPeriodo.forEach((l) => {
    l.recheios.forEach((r) => {
      if (parseFloat(r.perda) > 0) eventos.push({ produtoId: r.produtoId, etapa: "recheio", valor: parseFloat(r.perda), unidade: "kg", turno: r.turno, data: l.data, loteNumero: l.numero, usuario: r.usuario, obs: r.observacoes });
    });
    l.massas.forEach((m) => {
      if (parseFloat(m.perda) > 0) eventos.push({ produtoId: m.produtoId, etapa: "massa", valor: parseFloat(m.perda), unidade: "kg", turno: m.turno, data: l.data, loteNumero: l.numero, usuario: m.usuario, obs: m.observacoes });
    });
    l.modelagens.forEach((md) => {
      if (parseFloat(md.perda) > 0) eventos.push({ produtoId: md.produtoId, etapa: "modelagem", valor: parseFloat(md.perda), unidade: "kg", turno: md.turno, data: l.data, loteNumero: l.numero, usuario: md.usuario, obs: md.observacoes });
    });
    l.embalagens.forEach((e) => {
      if (parseFloat(e.perda) > 0) eventos.push({ produtoId: e.produtoId, etapa: "embalagem", valor: parseFloat(e.perda), unidade: "kg", turno: e.turno, data: l.data, loteNumero: l.numero, usuario: e.usuario, obs: e.observacoes });
    });
    (l.perdas || []).forEach((p) => {
      eventos.push({ produtoId: p.produtoId, etapa: "sobra-" + p.etapa, valor: parseFloat(p.peso) || 0, unidade: "kg", turno: p.turno, data: l.data, loteNumero: l.numero, usuario: p.usuario, obs: p.motivo });
    });
  });

  const eventosFiltrados = eventos
    .filter((e) => filtroProduto === "todos" || e.produtoId === filtroProduto)
    .filter((e) => filtroEtapa === "todas" || (filtroEtapa === "sobra" ? e.etapa.startsWith("sobra-") : e.etapa === filtroEtapa))
    .filter((e) => filtroTurno === "todos" || e.turno === filtroTurno)
    .sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : 0));

  const totalKg = eventosFiltrados.filter((e) => e.unidade === "kg").reduce((s, e) => s + e.valor, 0);
  const totalUn = eventosFiltrados.filter((e) => e.unidade === "un").reduce((s, e) => s + e.valor, 0);

  const produtosComPerda = [...new Set(eventos.map((e) => e.produtoId))];

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onBack} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="font-bold text-lg mb-1" style={{ color: C.black }}>Controle de Perdas</div>
      <div className="text-sm mb-4" style={{ color: C.gray500 }}>Todas as perdas registradas — recheio, massa, modelagem, embalagem e sobras descartadas.</div>

      <div className="flex gap-2 mb-3">
        {[
          { id: "hoje", label: "Hoje" },
          { id: "semana", label: "Semana" },
          { id: "mes", label: "Mês" },
          { id: "tudo", label: "Tudo" },
        ].map((p) => (
          <button
            key={p.id}
            onClick={() => setPeriodo(p.id)}
            className="flex-1 rounded-lg py-2 text-[11px] font-semibold"
            style={{ background: periodo === p.id ? C.red : C.white, color: periodo === p.id ? C.white : C.gray900 }}
          >
            {p.label}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-3 gap-2 mb-4">
        <select value={filtroProduto} onChange={(e) => setFiltroProduto(e.target.value)} className="rounded-lg px-2 py-2 text-[11px] outline-none" style={{ background: C.white, color: C.black }}>
          <option value="todos">Todos produtos</option>
          {ativos.filter((p) => produtosComPerda.includes(p.id)).map((p) => (
            <option key={p.id} value={p.id}>{p.nome}</option>
          ))}
        </select>
        <select value={filtroEtapa} onChange={(e) => setFiltroEtapa(e.target.value)} className="rounded-lg px-2 py-2 text-[11px] outline-none" style={{ background: C.white, color: C.black }}>
          <option value="todas">Todas etapas</option>
          <option value="recheio">Recheio</option>
          <option value="massa">Massa</option>
          <option value="modelagem">Modelagem</option>
          <option value="embalagem">Embalagem</option>
          <option value="sobra">Sobras descartadas</option>
        </select>
        <select value={filtroTurno} onChange={(e) => setFiltroTurno(e.target.value)} className="rounded-lg px-2 py-2 text-[11px] outline-none" style={{ background: C.white, color: C.black }}>
          <option value="todos">Todos turnos</option>
          <option value="matutino">☀️ Matutino</option>
          <option value="vespertino">🌙 Vespertino</option>
        </select>
      </div>

      {carregando ? (
        <div className="rounded-2xl p-8 text-center" style={{ background: C.white }}>
          <Loader2 size={20} className="animate-spin mx-auto mb-2" color={C.gray500} />
          <div className="text-xs" style={{ color: C.gray500 }}>Carregando histórico...</div>
        </div>
      ) : (
        <>
          <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
            <div className="text-[11px] font-semibold mb-1" style={{ color: C.gray500 }}>TOTAL NO FILTRO ATUAL</div>
            <div className="text-xl font-bold" style={{ color: C.redDark }}>{totalKg.toFixed(1)} kg</div>
            <div className="text-[11px] mt-0.5" style={{ color: C.gray500 }}>{eventosFiltrados.length} registro(s)</div>
          </div>

          <div className="space-y-2">
            {eventosFiltrados.length === 0 && (
              <div className="rounded-2xl p-6 text-center" style={{ background: C.white }}>
                <div className="text-sm" style={{ color: C.gray500 }}>Nenhuma perda encontrada com esses filtros.</div>
              </div>
            )}
            {eventosFiltrados.map((e, i) => (
              <div key={i} className="rounded-xl p-3" style={{ background: C.white }}>
                <div className="flex items-center justify-between text-sm">
                  <span className="font-medium" style={{ color: C.black }}>{nomeProduto(e.produtoId)}</span>
                  <span style={{ color: C.redDark }}>{e.valor} {e.unidade}</span>
                </div>
                <div className="flex items-center justify-between text-[11px] mt-1" style={{ color: C.gray500 }}>
                  <span>{ETAPA_PERDA_LABEL[e.etapa]} · {e.turno === "matutino" ? "☀️" : "🌙"} · Lote {e.loteNumero} ({fmtData(e.data)})</span>
                </div>
                <div className="text-[11px] mt-0.5" style={{ color: C.gray500 }}>{e.usuario}</div>
                {e.obs && <div className="text-[11px] mt-1 italic" style={{ color: C.gray500 }}>{e.obs}</div>}
              </div>
            ))}
          </div>
        </>
      )}
    </main>
  );
}

function DashboardScreen({ produtos, lote, planos, historicoLotes, onCarregarHistorico, onOpenPerdas, onBack }) {
  const [periodo, setPeriodo] = useState("hoje"); // hoje | semana | mes
  const [carregando, setCarregando] = useState(true);

  useEffect(() => {
    (async () => {
      await onCarregarHistorico();
      setCarregando(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const hojeISO = localISO();
  const semanaAtual = segundaFeiraDe(hojeISO);
  const mesAtual = hojeISO.slice(0, 7); // YYYY-MM

  // Junta o histórico carregado com o lote de hoje (que pode estar mais atualizado em memória)
  const todosLotes = [...historicoLotes.filter((l) => !(l.ano === lote.ano && l.numero === lote.numero)), lote];

  const lotesPeriodo = todosLotes.filter((l) => {
    if (periodo === "hoje") return l.data === hojeISO;
    if (periodo === "semana") return l.data >= semanaAtual && l.data <= hojeISO;
    return l.data.slice(0, 7) === mesAtual;
  });

  const ativos = produtos.filter((p) => p.status === "ativo");

  function qtdEsperadaAgg(produto, lotes) {
    let total = 0;
    lotes.forEach((l) => {
      if (produto.pesoRecheio > 0) {
        const peso = l.recheios.filter((r) => r.produtoId === produto.id).reduce((s, r) => s + (parseFloat(r.peso) || 0), 0);
        total += (peso * 1000) / produto.pesoRecheio;
      } else if (produto.pesoMassa > 0) {
        const peso = l.massas.filter((m) => m.produtoId === produto.id).reduce((s, m) => s + (parseFloat(m.peso) || 0), 0);
        total += (peso * 1000) / produto.pesoMassa;
      }
    });
    return Math.round(total);
  }
  function embaladoAgg(produtoId, lotes) {
    return lotes.reduce((s, l) => s + l.embalagens.filter((e) => e.produtoId === produtoId).reduce((s2, e) => s2 + (parseInt(e.quantidadeEmbalada) || 0), 0), 0);
  }
  function perdaProdutoAgg(produtoId, lotes) {
    return lotes.reduce((s, l) => {
      const r = l.recheios.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      const m = l.massas.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      const md = l.modelagens.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      const e = l.embalagens.filter((x) => x.produtoId === produtoId).reduce((s2, x) => s2 + (parseFloat(x.perda) || 0), 0);
      return s + r + m + md + e;
    }, 0);
  }

  const porProduto = ativos
    .map((p) => ({ produto: p, esperado: qtdEsperadaAgg(p, lotesPeriodo), embalado: embaladoAgg(p.id, lotesPeriodo), perdaKg: perdaProdutoAgg(p.id, lotesPeriodo) }))
    .filter((x) => x.esperado > 0 || x.embalado > 0 || x.perdaKg > 0);

  const totalEsperado = porProduto.reduce((s, x) => s + x.esperado, 0);
  const totalEmbalado = porProduto.reduce((s, x) => s + x.embalado, 0);
  const rendimento = statusRendimento(totalEmbalado, totalEsperado);

  const perdaRecheioKg = lotesPeriodo.reduce((s, l) => s + l.recheios.reduce((s2, r) => s2 + (parseFloat(r.perda) || 0), 0), 0);
  const perdaMassaKg = lotesPeriodo.reduce((s, l) => s + l.massas.reduce((s2, m) => s2 + (parseFloat(m.perda) || 0), 0), 0);
  const perdaModelagemKg = lotesPeriodo.reduce((s, l) => s + l.modelagens.reduce((s2, m) => s2 + (parseFloat(m.perda) || 0), 0), 0);
  const perdaEmbalagemKg = lotesPeriodo.reduce((s, l) => s + l.embalagens.reduce((s2, e) => s2 + (parseFloat(e.perda) || 0), 0), 0);
  const perdaSobrasKg = lotesPeriodo.reduce((s, l) => s + (l.perdas || []).reduce((s2, p) => s2 + (parseFloat(p.peso) || 0), 0), 0);
  const perdasKgTotal = perdaRecheioKg + perdaMassaKg + perdaModelagemKg + perdaEmbalagemKg;

  const rankingProdutos = [...porProduto].sort((a, b) => b.embalado - a.embalado).slice(0, 5);
  const rankingPerdas = [...porProduto].filter((x) => x.perdaKg > 0).sort((a, b) => b.perdaKg - a.perdaKg).slice(0, 5);

  // Produção por turno — só faz sentido para hoje (nos demais períodos os turnos se misturam entre dias)
  function embaladoTurnoHoje(turno) {
    return lote.embalagens.filter((e) => e.turno === turno).reduce((s, e) => s + (parseInt(e.quantidadeEmbalada) || 0), 0);
  }
  const embaladoMatutinoHoje = embaladoTurnoHoje("matutino");
  const embaladoVespertinoHoje = embaladoTurnoHoje("vespertino");
  const maxTurno = Math.max(embaladoMatutinoHoje, embaladoVespertinoHoje, 1);

  // Planejado x Produzido da semana atual (em kg de recheio/massa lançado)
  const planoSemana = planos.find((p) => p.semana === semanaAtual);
  const planejadoSemanaKg = planoSemana
    ? Object.values(planoSemana.dias || {}).reduce((s, d) => {
        const itens = [...(d.matutino || []), ...(d.vespertino || [])];
        return s + itens.reduce((s2, it) => s2 + (parseFloat(it.quantidade) || 0), 0);
      }, 0)
    : 0;
  const lotesSemana = todosLotes.filter((l) => l.data >= semanaAtual && l.data <= hojeISO);
  const produzidoSemanaKg =
    lotesSemana.reduce((s, l) => s + l.recheios.reduce((s2, r) => s2 + (parseFloat(r.peso) || 0), 0), 0) +
    lotesSemana.reduce((s, l) => s + l.massas.reduce((s2, m) => s2 + (parseFloat(m.peso) || 0), 0), 0);

  const ultimosLotes = [...todosLotes].sort((a, b) => (a.data < b.data ? 1 : -1)).slice(0, 8);

  return (
    <main className="flex-1 max-w-md w-full mx-auto px-4 pt-4 pb-24">
      <button onClick={onBack} className="flex items-center gap-1 text-sm mb-4" style={{ color: C.gray500 }}>
        <ArrowLeft size={16} /> Voltar
      </button>

      <div className="font-bold text-lg mb-3" style={{ color: C.black }}>Dashboard</div>

      <div className="flex gap-2 mb-4">
        {[
          { id: "hoje", label: "Hoje" },
          { id: "semana", label: "Semana" },
          { id: "mes", label: "Mês" },
        ].map((p) => (
          <button
            key={p.id}
            onClick={() => setPeriodo(p.id)}
            className="flex-1 rounded-lg py-2 text-xs font-semibold"
            style={{ background: periodo === p.id ? C.red : C.white, color: periodo === p.id ? C.white : C.gray900 }}
          >
            {p.label}
          </button>
        ))}
      </div>

      {carregando ? (
        <div className="rounded-2xl p-8 text-center" style={{ background: C.white }}>
          <Loader2 size={20} className="animate-spin mx-auto mb-2" color={C.gray500} />
          <div className="text-xs" style={{ color: C.gray500 }}>Carregando histórico...</div>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-2 gap-3 mb-4">
            <div className="rounded-2xl p-4" style={{ background: C.white }}>
              <div className="text-[11px] font-semibold" style={{ color: C.gray500 }}>PRODUÇÃO</div>
              <div className="text-xl font-bold mt-1" style={{ color: C.black }}>{totalEmbalado.toLocaleString("pt-BR")}</div>
              <div className="text-[11px]" style={{ color: C.gray500 }}>de {totalEsperado.toLocaleString("pt-BR")} esperadas</div>
            </div>
            <div className="rounded-2xl p-4" style={{ background: C.white }}>
              <div className="text-[11px] font-semibold" style={{ color: C.gray500 }}>RENDIMENTO</div>
              <div className="text-xl font-bold mt-1 flex items-center gap-1" style={{ color: rendimento.color }}>
                {rendimento.emoji} {rendimento.pct != null ? `${rendimento.pct.toFixed(0)}%` : "-"}
              </div>
              <div className="text-[11px]" style={{ color: C.gray500 }}>{rendimento.label}</div>
            </div>
          </div>

          {rankingProdutos.length > 0 && (
            <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
              <div className="text-[11px] font-semibold mb-2" style={{ color: C.gray500 }}>🏆 RANKING DE PRODUTOS</div>
              <div className="space-y-2">
                {rankingProdutos.map((x, i) => {
                  const pct = Math.max(...rankingProdutos.map((r) => r.embalado)) > 0 ? (x.embalado / Math.max(...rankingProdutos.map((r) => r.embalado))) * 100 : 0;
                  return (
                    <div key={x.produto.id}>
                      <div className="flex items-center justify-between text-xs mb-0.5">
                        <span style={{ color: C.gray900 }}>{i + 1}. {x.produto.nome}</span>
                        <span style={{ color: C.gray500 }}>{x.embalado.toLocaleString("pt-BR")} un.</span>
                      </div>
                      <div className="h-1.5 rounded-full" style={{ background: C.gray100 }}>
                        <div className="h-1.5 rounded-full" style={{ width: `${pct}%`, background: C.red }} />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {rankingPerdas.length > 0 && (
            <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
              <div className="text-[11px] font-semibold mb-2" style={{ color: C.gray500 }}>📉 RANKING DE PERDAS</div>
              <div className="space-y-2">
                {rankingPerdas.map((x, i) => {
                  const maxPerda = Math.max(...rankingPerdas.map((r) => r.perdaKg));
                  const pct = maxPerda > 0 ? (x.perdaKg / maxPerda) * 100 : 0;
                  return (
                    <div key={x.produto.id}>
                      <div className="flex items-center justify-between text-xs mb-0.5">
                        <span style={{ color: C.gray900 }}>{i + 1}. {x.produto.nome}</span>
                        <span style={{ color: C.redDark }}>{x.perdaKg.toFixed(1)} kg</span>
                      </div>
                      <div className="h-1.5 rounded-full" style={{ background: C.gray100 }}>
                        <div className="h-1.5 rounded-full" style={{ width: `${pct}%`, background: "#CA8A04" }} />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
            <div className="text-[11px] font-semibold mb-2" style={{ color: C.gray500 }}>PRODUÇÃO POR TURNO (HOJE)</div>
            <div className="space-y-2">
              <div>
                <div className="flex items-center justify-between text-xs mb-0.5">
                  <span style={{ color: C.gray900 }}>☀️ Matutino</span>
                  <span style={{ color: C.gray500 }}>{embaladoMatutinoHoje.toLocaleString("pt-BR")} un.</span>
                </div>
                <div className="h-1.5 rounded-full" style={{ background: C.gray100 }}>
                  <div className="h-1.5 rounded-full" style={{ width: `${(embaladoMatutinoHoje / maxTurno) * 100}%`, background: C.red }} />
                </div>
              </div>
              <div>
                <div className="flex items-center justify-between text-xs mb-0.5">
                  <span style={{ color: C.gray900 }}>🌙 Vespertino</span>
                  <span style={{ color: C.gray500 }}>{embaladoVespertinoHoje.toLocaleString("pt-BR")} un.</span>
                </div>
                <div className="h-1.5 rounded-full" style={{ background: C.gray100 }}>
                  <div className="h-1.5 rounded-full" style={{ width: `${(embaladoVespertinoHoje / maxTurno) * 100}%`, background: "#2563EB" }} />
                </div>
              </div>
            </div>
          </div>

          <div className="rounded-2xl p-4 mb-4" style={{ background: C.white }}>
            <div className="text-[11px] font-semibold mb-2" style={{ color: C.gray500 }}>PLANEJADO × PRODUZIDO (SEMANA ATUAL)</div>
            {planejadoSemanaKg === 0 ? (
              <div className="text-sm" style={{ color: C.gray500 }}>Nenhum planejamento cadastrado para esta semana.</div>
            ) : (
              <>
                <div className="flex items-center justify-between text-xs mb-1">
                  <span style={{ color: C.gray900 }}>Planejado: <strong>{planejadoSemanaKg.toFixed(1)}kg</strong></span>
                  <span style={{ color: C.gray900 }}>Produzido: <strong>{produzidoSemanaKg.toFixed(1)}kg</strong></span>
                </div>
                <div className="h-2 rounded-full" style={{ background: C.gray100 }}>
                  <div
                    className="h-2 rounded-full"
                    style={{ width: `${Math.min(100, (produzidoSemanaKg / planejadoSemanaKg) * 100)}%`, background: produzidoSemanaKg >= planejadoSemanaKg ? "#16A34A" : C.red }}
                  />
                </div>
              </>
            )}
          </div>

          <button onClick={onOpenPerdas} className="w-full rounded-2xl p-4 mb-4 text-left" style={{ background: C.white }}>
            <div className="flex items-center justify-between mb-2">
              <div className="text-[11px] font-semibold" style={{ color: C.gray500 }}>PERDAS POR ETAPA</div>
              <span className="text-[11px] font-semibold" style={{ color: C.red }}>Ver detalhes →</span>
            </div>
            <div className="grid grid-cols-2 gap-2 text-xs" style={{ color: C.gray900 }}>
              <div>Recheio: <strong>{perdaRecheioKg.toFixed(1)}kg</strong></div>
              <div>Massa: <strong>{perdaMassaKg.toFixed(1)}kg</strong></div>
              <div>Modelagem: <strong>{perdaModelagemKg.toFixed(1)}kg</strong></div>
              <div>Embalagem: <strong>{perdaEmbalagemKg.toFixed(1)}kg</strong></div>
            </div>
            <div className="text-[11px] mt-2 pt-2" style={{ color: C.gray500, borderTop: `1px solid ${C.gray200}` }}>
              Total: {perdasKgTotal.toFixed(1)}kg
              {perdaSobrasKg > 0 && <> · Sobras descartadas: {perdaSobrasKg.toFixed(1)}kg</>}
            </div>
          </button>

          <div className="rounded-2xl p-4" style={{ background: C.white }}>
            <div className="text-[11px] font-semibold mb-2" style={{ color: C.gray500 }}>ÚLTIMOS LOTES</div>
            <div className="space-y-1.5">
              {ultimosLotes.map((l) => {
                const esp = ativos.reduce((s, p) => s + qtdEsperadaAgg(p, [l]), 0);
                const emb = ativos.reduce((s, p) => s + embaladoAgg(p.id, [l]), 0);
                const st = statusRendimento(emb, esp);
                return (
                  <div key={`${l.ano}-${l.numero}`} className="flex items-center justify-between text-xs rounded-lg px-2.5 py-2" style={{ background: C.gray100 }}>
                    <span style={{ color: C.gray900 }}>
                      {l.status === "fechado" ? <Lock size={10} className="inline mr-1" /> : null}
                      Lote {l.numero} · {fmtData(l.data)}
                    </span>
                    <span style={{ color: C.gray500 }}>{st.emoji} {emb}/{esp}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </>
      )}
    </main>
  );
}

function ItemConferencia({ ok, aviso, children }) {
  const emoji = ok ? "✔️" : aviso ? "⚠️" : "❌";
  const color = ok ? C.gray900 : aviso ? "#92400E" : C.redDark;
  return (
    <div className="flex items-start gap-2 text-xs" style={{ color }}>
      <span>{emoji}</span>
      <span className="flex-1">{children}</span>
    </div>
  );
}

function AvisoSobra({ sobras, produtos, produtoId, etapa, onUsar, onPreencher }) {
  const livre = etapa === "massa"; // massa é base genérica, reaproveitável em qualquer produto
  const disponiveis = sobras.filter(
    (s) => s.status === "disponivel" && s.etapa === etapa && s.peso > 0 && (livre || s.produtoId === produtoId)
  );
  if (disponiveis.length === 0) return null;
  const total = disponiveis.reduce((s, x) => s + x.peso, 0);
  const maisProxima = [...disponiveis].sort((a, b) => (a.validade < b.validade ? -1 : 1))[0];
  const st = statusSobra(maisProxima);
  const origens = livre
    ? [...new Set(disponiveis.map((s) => s.produtoId))]
        .map((id) => produtos?.find((p) => p.id === id)?.nome || id)
        .join(", ")
    : null;
  return (
    <div className="rounded-xl p-3 mb-3 flex items-center justify-between gap-2" style={{ background: "#ECFDF5", border: "1px solid #A7F3D0" }}>
      <div className="text-xs" style={{ color: "#065F46" }}>
        <div className="font-semibold flex items-center gap-1"><Archive size={12} /> Sobra disponível: {total.toFixed(2)} kg</div>
        <div>{st.emoji} {st.label}{livre && origens && <span> · de: {origens}</span>}</div>
      </div>
      <button
        onClick={() => {
          onPreencher(total.toFixed(2));
          disponiveis.forEach((s) => onUsar(s.id));
        }}
        className="text-xs font-semibold px-3 py-1.5 rounded-lg text-white shrink-0"
        style={{ background: "#059669" }}
      >
        Usar sobra
      </button>
    </div>
  );
}

function LoteDoDiaCard({ lote }) {
  return (
    <div className="rounded-2xl p-4 mb-3" style={{ background: C.white }}>
      <div className="text-[10px] font-semibold" style={{ color: C.gray500 }}>LOTE DO DIA</div>
      <div className="flex items-center justify-between mt-1">
        <div className="text-2xl font-bold" style={{ color: C.red }}>{lote.numero}</div>
        <div className="text-xs" style={{ color: C.gray500 }}>{fmtData(lote.data)}</div>
      </div>
    </div>
  );
}

function MetaProduzidoCard({ meta, produzido, unidade }) {
  const pct = meta > 0 ? Math.min(100, (produzido / meta) * 100) : 0;
  const casas = unidade === "kg" ? 1 : 0;
  return (
    <div className="rounded-2xl p-4 mb-3" style={{ background: `linear-gradient(135deg, ${C.red}, ${C.redDark})` }}>
      <div className="flex items-center justify-between">
        <div>
          <div className="text-[10px] font-semibold" style={{ color: "rgba(255,255,255,0.8)" }}>META DO DIA</div>
          <div className="text-lg font-bold text-white">{meta.toFixed(casas)} {unidade}</div>
        </div>
        <div className="text-right">
          <div className="text-[10px] font-semibold" style={{ color: "rgba(255,255,255,0.8)" }}>PRODUZIDO</div>
          <div className="text-lg font-bold text-white">{produzido.toFixed(casas)} {unidade}</div>
        </div>
      </div>
      <div className="h-2 rounded-full mt-3" style={{ background: "rgba(255,255,255,0.3)" }}>
        <div className="h-2 rounded-full" style={{ width: `${pct}%`, background: C.white }} />
      </div>
      <div className="text-right text-xs text-white mt-1 font-semibold">{pct.toFixed(0)}%</div>
    </div>
  );
}

function ProdutoProgressoRow({ produto, meta, produzido, unidade }) {
  const pct = meta > 0 ? Math.min(100, (produzido / meta) * 100) : 0;
  const casas = unidade === "kg" ? 1 : 0;
  return (
    <div className="flex items-center gap-3 py-2">
      <div className="w-10 h-10 rounded-full flex items-center justify-center text-lg shrink-0" style={{ background: C.gray100 }}>
        {iconeProduto(produto.nome)}
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-sm font-medium truncate" style={{ color: C.black }}>{produto.nome}</div>
        <div className="text-[11px]" style={{ color: C.gray500 }}>
          Meta: {meta.toFixed(casas)}{unidade} · Produzido: {produzido.toFixed(casas)}{unidade}
        </div>
        <div className="h-1.5 rounded-full mt-1" style={{ background: C.gray100 }}>
          <div className="h-1.5 rounded-full" style={{ width: `${pct}%`, background: C.red }} />
        </div>
      </div>
      <div className="text-xs font-semibold shrink-0" style={{ color: C.gray900 }}>{pct.toFixed(0)}%</div>
    </div>
  );
}

function ProducaoPorTipoCard({ titulo, itens, unidade, onVerMais }) {
  if (itens.length === 0) return null;
  return (
    <div className="rounded-2xl p-4 mb-3" style={{ background: C.white }}>
      <div className="flex items-center justify-between mb-1">
        <div className="text-sm font-semibold" style={{ color: C.black }}>{titulo}</div>
        {onVerMais && <button onClick={onVerMais} className="text-xs font-semibold" style={{ color: C.red }}>Ver mais</button>}
      </div>
      <div className="divide-y" style={{ borderColor: C.gray200 }}>
        {itens.map((x) => (
          <ProdutoProgressoRow key={x.produto.id} produto={x.produto} meta={x.meta} produzido={x.produzido} unidade={unidade} />
        ))}
      </div>
    </div>
  );
}

function PerdasDoDiaRow({ perdaValor, unidade, pctTexto, onClick }) {
  const casas = unidade === "kg" ? 1 : 0;
  return (
    <button onClick={onClick} className="w-full flex items-center justify-between rounded-xl px-4 py-3 mb-3" style={{ background: "#FEF3C7" }}>
      <span className="flex items-center gap-2 text-sm font-semibold" style={{ color: "#92400E" }}>
        <AlertTriangle size={15} /> Perdas do dia
      </span>
      <span className="flex items-center gap-1 text-sm font-semibold" style={{ color: "#92400E" }}>
        {perdaValor.toFixed(casas)}{unidade}{pctTexto ? ` (${pctTexto})` : ""}
        <ChevronDown size={14} style={{ transform: "rotate(-90deg)" }} />
      </span>
    </button>
  );
}

function BarraDataTrabalho({ lote, dataTrabalho, trocando, onTrocar }) {
  const hoje = localISO();
  const ehHoje = dataTrabalho === hoje;

  if (ehHoje) {
    return (
      <div className="flex items-center justify-between rounded-xl px-3 py-2 mb-3" style={{ background: C.white, border: `1px solid ${C.gray200}` }}>
        <span className="text-[11px]" style={{ color: C.gray500 }}>
          Lançando em: <strong style={{ color: C.gray900 }}>Hoje</strong> · Lote {lote.numero}
        </span>
        <input
          type="date"
          value={dataTrabalho}
          max={hoje}
          onChange={(e) => e.target.value && onTrocar(e.target.value)}
          disabled={trocando}
          className="text-[11px] rounded-lg px-2 py-1 outline-none"
          style={{ background: C.gray100, color: C.gray900 }}
        />
      </div>
    );
  }

  return (
    <div className="rounded-xl p-3 mb-3" style={{ background: "#FEF3C7", border: "1px solid #FDE68A" }}>
      <div className="flex items-center justify-between gap-2">
        <div className="text-xs" style={{ color: "#92400E" }}>
          <div className="font-bold flex items-center gap-1"><CalendarDays size={13} /> Lançando para {fmtData(dataTrabalho)}</div>
          <div>Lote {lote.numero} — não é o dia de hoje. {lote.status === "fechado" && "Este lote está fechado."}</div>
        </div>
        <button
          onClick={() => onTrocar(hoje)}
          disabled={trocando}
          className="text-[11px] font-semibold px-2.5 py-1.5 rounded-lg shrink-0"
          style={{ background: "#92400E", color: C.white }}
        >
          Voltar pra hoje
        </button>
      </div>
      <input
        type="date"
        value={dataTrabalho}
        max={hoje}
        onChange={(e) => e.target.value && onTrocar(e.target.value)}
        disabled={trocando}
        className="w-full mt-2 text-[11px] rounded-lg px-2 py-1.5 outline-none"
        style={{ background: C.white, color: C.gray900 }}
      />
    </div>
  );
}

function ComingSoon({ label }) {
  const names = { recheio: "Recheio", massa: "Massa", modelagem: "Modelagem", embalagem: "Embalagem", relatorios: "Relatórios" };
  return (
    <div className="rounded-2xl p-8 text-center mt-8" style={{ background: C.white }}>
      <div className="text-sm font-semibold" style={{ color: C.black }}>{names[label]}</div>
      <div className="text-xs mt-1" style={{ color: C.gray500 }}>Módulo será construído na próxima etapa.</div>
    </div>
  );
}

function BottomNav({ tab, setTab }) {
  const items = [
    { id: "home", label: "Home", icon: HomeIcon },
    { id: "recheio", label: "Recheio", icon: Soup },
    { id: "massa", label: "Massa", icon: Wheat },
    { id: "modelagem", label: "Modelagem", icon: Layers },
    { id: "embalagem", label: "Embalagem", icon: Package },
    { id: "relatorios", label: "Relatórios", icon: FileText },
  ];
  return (
    <nav className="fixed bottom-0 left-0 right-0 z-20" style={{ background: C.white, borderTop: `1px solid ${C.gray200}` }}>
      <div className="max-w-md mx-auto grid grid-cols-6">
        {items.map((it) => {
          const Icon = it.icon;
          const active = tab === it.id;
          return (
            <button key={it.id} onClick={() => setTab(it.id)} className="flex flex-col items-center gap-0.5 py-2.5">
              <Icon size={18} color={active ? C.red : C.gray500} />
              <span className="text-[9px]" style={{ color: active ? C.red : C.gray500 }}>{it.label}</span>
            </button>
          );
        })}
      </div>
    </nav>
  );
}

function Toast({ toast }) {
  return (
    <div className="fixed top-16 left-1/2 -translate-x-1/2 z-30 px-4 py-2 rounded-full text-sm font-medium text-white" style={{ background: toast.kind === "warn" ? C.gray900 : C.red }}>
      {toast.msg}
    </div>
  );
}
